/* DAWAH X — ahmad, অধ্যায় 98 · খণ্ড 98 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][98]=[[19401,19401,"","","‏ ‏حَدَّثَنَا ‏ ‏نُوحُ بْنُ حَبِيبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ غِيَاثِ بْنِ طَلْقِ بْنِ مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏ثَعْلَبَةَ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَجَبًا لِلْمُؤْمِنِ لَا يَقْضِي اللَّهُ لَهُ شَيْئًا إِلَّا كَانَ خَيْرًا لَهُ ‏","","",""],[19402,19402,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْعَلَاءِ ‏ ‏قَالَ قَالَ ‏ ‏رَجُلٌ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ وَالنَّاسُ يَعْتَقِبُونَ وَفِي الظَّهْرِ قِلَّةٌ ‏ ‏فَحَانَتْ ‏ ‏نَزْلَةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَزْلَتِي فَلَحِقَنِي مِنْ بَعْدِي ‏ ‏فَضَرَبَ ‏ ‏مَنْكِبَيَّ ‏ ‏فَقَالَ ‏ ‏قُلْ أَعُوذُ بِرَبِّ ‏ ‏الْفَلَقِ ‏ ‏فَقُلْتُ ‏ ‏أَعُوذُ بِرَبِّ ‏ ‏الْفَلَقِ ‏ ‏فَقَرَأَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَرَأْتُهَا مَعَهُ ثُمَّ قَالَ ‏ ‏قُلْ أَعُوذُ بِرَبِّ النَّاسِ ‏ ‏فَقَرَأَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَرَأْتُهَا مَعَهُ قَالَ إِذَا أَنْتَ صَلَّيْتَ فَاقْرَأْ بِهِمَا ‏","","",""],[19403,19403,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَلْقَمَةَ بْنِ عَبْدِ اللَّهِ الْمُزَنِيِّ ‏ ‏عَنْ ‏ ‏رِجَالٍ ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَتَّقِ اللَّهَ عَزَّ وَجَلَّ وَلْيُكْرِمْ جَارَهُ وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَتَّقِ اللَّهَ وَلْيُكْرِمْ ضَيْفَهُ وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَتَّقِ اللَّهَ وَلْيَقُلْ حَقًّا أَوْ لِيَسْكُتْ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَلْقَمَةَ بْنِ عَبْدِ اللَّهِ الْمُزَنِيِّ ‏ ‏عَنْ ‏ ‏رِجَالٍ ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ ‏ ‏مِثْلَهُ ‏","","",""],[19404,19404,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏نَصْرِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْهُمْ ‏ ‏أَنَّهُ أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَسْلَمَ عَلَى أَنَّهُ لَا ‏ ‏يُصَلِّي إِلَّا صَلَاتَيْنِ فَقَبِلَ ذَلِكَ مِنْهُ ‏","","",""],[19405,19405,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏قَالَ وَأَخْبَرَنِي ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏بَنِي سَلِيطٍ ‏ ‏قَالَ ‏ ‏دُفِعْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَمِعْتُهُ يَقُولُ ‏ ‏الْمُسْلِمُ أَخُو الْمُسْلِمِ لَا يَظْلِمُهُ وَلَا يَخْذُلُهُ التَّقْوَى هَاهُنَا التَّقْوَى هَاهُنَا مَرَّتَيْنِ أَوْ ثَلَاثًا وَأَشَارَ بِيَدِهِ إِلَى صَدْرِهِ ‏","","",""],[19406,19406,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سَوَادَةُ بْنُ أَبِي الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَعْقِلِ بْنِ يَسَارٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّمَا رَاعٍ اسْتُرْعِيَ رَعِيَّةً فَغَشَّهَا فَهُوَ فِي النَّارِ ‏","","",""],[19407,19407,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أَبِي خَالِدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏إِسْمَاعِيلَ الْبَصْرِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏ابْنَةِ مَعْقِلِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِيهَا ‏ ‏مَعْقِلٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيْسَ مِنْ وَالِي أُمَّةٍ قَلَّتْ أَوْ كَثُرَتْ لَا يَعْدِلُ فِيهَا إِلَّا كَبَّهُ اللَّهُ تَبَارَكَ وَتَعَالَى عَلَى وَجْهِهِ فِي النَّارِ ‏","","",""],[19408,19408,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏أَنَّ ‏ ‏مَعْقِلَ بْنَ يَسَارٍ ‏ ‏اشْتَكَى ‏ ‏فَدَخَلَ عَلَيْهِ ‏ ‏عَبْدُ اللَّهِ بْنُ زِيَادٍ ‏ ‏يَعْنِي ‏ ‏يَعُودُهُ ‏ ‏فَقَالَ أَمَا إِنِّي سَأُحَدِّثُكَ حَدِيثًا لَمْ أَكُنْ حَدَّثْتُكَ بِهِ إِنِّي ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏يَسْتَرْعِي اللَّهُ تَبَارَكَ وَتَعَالَى عَبْدًا رَعِيَّةً فَيَمُوتُ يَوْمَ يَمُوتُ وَهُوَ لَهَا غَاشٌّ إِلَّا حَرَّمَ اللَّهُ عَلَيْهِ الْجَنَّةَ ‏","","",""],[19409,19409,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عِيَاضًا أَبَا خَالِدٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَجُلَيْنِ يَخْتَصِمَانِ عِنْدَ ‏ ‏مَعْقِلِ بْنِ يَسَارٍ ‏ ‏فَقَالَ ‏ ‏مَعْقِلُ بْنُ يَسَارٍ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَلَفَ عَلَى يَمِينٍ لِيَقْتَطِعَ بِهَا مَالَ رَجُلٍ لَقِيَ اللَّهَ وَهُوَ عَلَيْهِ غَضْبَانُ ‏","","",""],[19410,19410,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَبْدِ الْمَجِيدِ الثَّقَفِيُّ أَبُو مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنِ ‏ ‏الْحَكَمِ بْنِ عَبْدِ اللَّهِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏مَعْقِلِ بْنِ يَسَارٍ ‏ ‏أَنَّهُ ‏ ‏شَهِدَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏وَهُوَ رَافِعٌ غُصْنًا مِنْ أَغْصَانِ الشَّجَرَةِ بِيَدِهِ عَنْ رَأْسِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُبَايِعُ النَّاسَ فَبَايَعُوهُ عَلَى أَنْ لَا يَفِرُّوا وَهُمْ يَوْمَئِذٍ أَلْفٌ وَأَرْبَعُ مِائَةٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَمَانٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنِ ‏ ‏الْحَكَمِ بْنِ الْأَعْرَجِ ‏ { ‏يَدُ اللَّهِ فَوْقَ أَيْدِيهِمْ ‏} ‏قَالَ أَنْ لَا يَفِرُّوا ‏","","",""],[19411,19411,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏عِيَاضٌ أَبُو خَالِدٍ ‏ ‏قَالَ ‏ ‏كَانَ بَيْنَ جَارَيْنِ ‏ ‏لمَعْقِلِ بْنِ يَسَارٍ ‏ ‏كَلَامٌ فَصَارَتْ الْيَمِينُ عَلَى أَحَدِهِمَا ‏ ‏فَسَمِعْتُ ‏ ‏مَعْقِلَ بْنَ يَسَارٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَلَفَ عَلَى يَمِينٍ يَقْتَطِعُ بِهَا مَالَ أَخِيهِ لَقِيَ اللَّهَ وَهُوَ عَلَيْهِ غَضْبَانُ ‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ الْأَوْدِيِّ ‏ ‏عَنِ ‏ ‏ابْنَةِ مَعْقِلٍ الْمُزَنِيِّ ‏ ‏قَالَتْ ‏ ‏لَمَّا ثَقُلَ ‏ ‏أَبِي ‏ ‏أَتَاهُ ‏ ‏ابْنُ زِيَادٍ ‏ ‏وَسَاقَهُ ‏ ‏يَعْنِي وَسَاقَ الْحَدِيثَ ‏","","",""],[19412,19412,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ دَلْهَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏مَعْقِلِ بْنِ يَسَارٍ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏تَزَوَّجَ امْرَأَةً فَسَقَطَ شَعَرُهَا فَسُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْوِصَالِ ‏ ‏فَلَعَنَ ‏ ‏الْوَاصِلَةَ ‏ ‏وَالْمَوْصُولَةَ ‏","","",""],[19413,19413,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمُعَلَّى بْنُ زِيَادٍ الْقُرْدُوسِيُّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏عَنْ ‏ ‏مَعْقِلِ بْنِ يَسَارٍ الْمُزَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَمَلُ فِي ‏ ‏الْهَرْجِ ‏ ‏كَهِجْرَةٍ إِلَيَّ ‏","","",""],[19414,19414,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْمُثَنَّى بْنُ عَوْفٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ اللَّهِ الْجَسْرِيُّ ‏ ‏قَالَ سَأَلْتُ ‏ ‏مَعْقِلَ بْنَ يَسَارٍ ‏ ‏عَنْ الشَّرَابِ فَقَالَ كُنَّا ‏ ‏بِالْمَدِينَةِ ‏ ‏وَكَانَتْ كَثِيرَةَ التَّمْرِ ‏ ‏فَحَرَّمَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْفَضِيخَ ‏ ‏وَأَتَاهُ رَجُلٌ فَسَأَلَهُ عَنْ أُمٍّ لَهُ عَجُوزٍ كَبِيرَةٍ ‏ ‏أَنَسْقِيهَا ‏ ‏النَّبِيذَ ‏ ‏فَإِنَّهَا لَا تَأْكُلُ الطَّعَامَ فَنَهَاهُ ‏ ‏مَعْقِلٌ ‏","","",""],[19415,19415,"","","‏ ‏حَدَّثَنَا ‏ ‏عَارِمٌ ‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَعْقِلِ بْنِ يَسَارٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْبَقَرَةُ ‏ ‏سَنَامُ ‏ ‏الْقُرْآنِ وَذُرْوَتُهُ نَزَلَ مَعَ كُلِّ آيَةٍ مِنْهَا ثَمَانُونَ مَلَكًا وَاسْتُخْرِجَتْ ‏ { ‏لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ‏} ‏مِنْ تَحْتِ الْعَرْشِ فَوُصِلَتْ بِهَا أَوْ فَوُصِلَتْ بِسُورَةِ ‏ ‏الْبَقَرَةِ ‏ ‏وَيس ‏ ‏قَلْبُ الْقُرْآنِ لَا يَقْرَؤُهَا رَجُلٌ يُرِيدُ اللَّهَ تَبَارَكَ وَتَعَالَى وَالدَّارَ الْآخِرَةَ إِلَّا غُفِرَ لَهُ وَاقْرَءُوهَا عَلَى مَوْتَاكُمْ ‏","","",""],[19416,19416,"","","‏ ‏حَدَّثَنَا ‏ ‏عَارِمٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏وَلَيْسَ ‏ ‏بِالنَّهْدِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَعْقِلِ بْنِ يَسَارٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْرَءُوهَا عَلَى مَوْتَاكُمْ ‏ ‏يَعْنِي ‏ ‏يس ‏","","",""],[19417,19417,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الرَّبَابِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَعْقِلَ بْنَ يَسَارٍ ‏ ‏يَقُولُ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَسِيرٍ لَهُ فَنَزَلْنَا فِي مَكَانٍ كَثِيرِ الثُّومِ وَإِنَّ أُنَاسًا مِنْ الْمُسْلِمِينَ أَصَابُوا مِنْهُ ثُمَّ جَاءُوا إِلَى الْمُصَلَّى يُصَلُّونَ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَهَاهُمْ عَنْهَا ثُمَّ جَاءُوا بَعْدَ ذَلِكَ إِلَى الْمُصَلَّى فَنَهَاهُمْ عَنْهَا ثُمَّ جَاءُوا بَعْدَ ذَلِكَ إِلَى الْمُصَلَّى فَنَهَاهُمْ عَنْهَا ثُمَّ جَاءُوا بَعْدَ ذَلِكَ إِلَى الْمُصَلَّى فَوَجَدَ رِيحَهَا مِنْهُمْ فَقَالَ ‏ ‏مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ فَلَا يَقْرَبْنَا فِي مَسْجِدِنَا ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ أَبِي الْقَاسِمِ الْحَنَفِيُّ أَبُو عَزَّةَ الدَّبَّاغُ ‏ ‏عَنْ ‏ ‏أَبِي الرَّبَابِ ‏ ‏عَنْ ‏ ‏مَعْقِلِ بْنِ يَسَارٍ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَسِيرٍ لَهُ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو يَعْقُوبَ يَعْنِي إِسْحَاقَ بْنَ عُثْمَانَ ‏ ‏حَدَّثَنِي ‏ ‏حُمْرَانُ ‏ ‏أَوْ ‏ ‏حَمْدَانُ ‏ ‏مَوْلَى ‏ ‏مَعْقِلِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏مَعْقِلِ بْنِ يَسَارٍ ‏ ‏قَالَ ‏ ‏صَحِبْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَذَا وَكَذَا ‏","","",""],[19418,19418,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏أَبِي شَيْبَةَ يَحْيَى بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَبِي أُنَيْسَةَ ‏ ‏عَنْ ‏ ‏نُفَيْعِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏مَعْقِلٍ الْمُزَنِيِّ ‏ ‏قَالَ ‏ ‏أَمَرَنِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ أَقْضِيَ بَيْنَ قَوْمٍ فَقُلْتُ مَا أَحْسَنَ أَنْ أَقْضِيَ يَا رَسُولَ اللَّهِ قَالَ اللَّهُ مَعَ الْقَاضِي مَا لَمْ ‏ ‏يَحِفْ ‏ ‏عَمْدًا ‏","","",""],[19419,19419,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ يَعْنِي ابْنَ طَهْمَانَ أَبُو الْعَلَاءِ الْخَفَّافُ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعُ بْنُ أَبِي نَافِعٍ ‏ ‏عَنْ ‏ ‏مَعْقِلِ بْنِ يَسَارٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قَالَ حِينَ يُصْبِحُ ثَلَاثَ مَرَّاتٍ أَعُوذُ بِاللَّهِ السَّمِيعِ الْعَلِيمِ مِنْ الشَّيْطَانِ الرَّجِيمِ وَقَرَأَ الثَّلَاثَ آيَاتٍ مِنْ آخِرِ سُورَةِ ‏ ‏الْحَشْرِ ‏ ‏وَكَّلَ اللَّهُ بِهِ سَبْعِينَ أَلْفَ مَلَكٍ يُصَلُّونَ عَلَيْهِ حَتَّى يُمْسِيَ إِنْ مَاتَ فِي ذَلِكَ الْيَوْمِ مَاتَ شَهِيدًا وَمَنْ قَالَهَا حِينَ يُمْسِي كَانَ بِتِلْكَ الْمَنْزِلَةِ ‏","","",""],[19420,19420,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ يَعْنِي ابْنَ طَهْمَانَ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ أَبِي نَافِعٍ ‏ ‏عَنْ ‏ ‏مَعْقِلِ بْنِ يَسَارٍ ‏ ‏قَالَ ‏ ‏وَضَّأْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ فَقَالَ ‏ ‏هَلْ لَكَ فِي ‏ ‏فَاطِمَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏تَعُودُهَا فَقُلْتُ نَعَمْ فَقَامَ مُتَوَكِّئًا عَلَيَّ فَقَالَ أَمَا إِنَّهُ سَيَحْمِلُ ثِقَلَهَا غَيْرُكَ وَيَكُونُ أَجْرُهَا لَكَ قَالَ فَكَأَنَّهُ لَمْ يَكُنْ عَلَيَّ شَيْءٌ حَتَّى دَخَلْنَا عَلَى ‏ ‏فَاطِمَةَ ‏ ‏عَلَيْهَا السَّلَام ‏ ‏فَقَالَ لَهَا كَيْفَ تَجِدِينَكِ قَالَتْ وَاللَّهِ لَقَدْ اشْتَدَّ حُزْنِي وَاشْتَدَّتْ فَاقَتِي وَطَالَ سَقَمِي ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏فِي هَذَا الْحَدِيثِ ‏ ‏قَالَ ‏ ‏أَوَ مَا تَرْضَيْنَ أَنِّي زَوَّجْتُكِ أَقْدَمَ أُمَّتِي سِلْمَا وَأَكْثَرَهُمْ عِلْمًا وَأَعْظَمَهُمْ حِلْمًا ‏","","",""],[19421,19421,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏مَعْقِلِ بْنِ يَسَارٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَلْبَثُ ‏ ‏الْجَوْرُ ‏ ‏بَعْدِي ‏ ‏إِلَّا قَلِيلًا حَتَّى يَطْلُعَ فَكُلَّمَا طَلَعَ مِنْ ‏ ‏الْجَوْرِ ‏ ‏شَيْءٌ ذَهَبَ مِنْ الْعَدْلِ مِثْلُهُ حَتَّى يُولَدَ فِي ‏ ‏الْجَوْرِ ‏ ‏مَنْ لَا يَعْرِفُ غَيْرَهُ ثُمَّ يَأْتِي اللَّهُ تَبَارَكَ وَتَعَالَى بِالْعَدْلِ فَكُلَّمَا جَاءَ مِنْ الْعَدْلِ شَيْءٌ ذَهَبَ مِنْ ‏ ‏الْجَوْرِ ‏ ‏مِثْلُهُ حَتَّى يُولَدَ فِي الْعَدْلِ مَنْ لَا يَعْرِفُ غَيْرَهُ ‏","","",""],[19422,19422,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ الْهَيْثَمِ أَبُو قَطَنٍ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ يَعْنِي ابْنَ أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏شَهِدَ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ وَقَدْ كَانَ جَمَعَ ‏ ‏أَصْحَابَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَيَاتِهِ وَصِحَّتِهِ ‏ ‏فَنَاشَدَهُمْ ‏ ‏اللَّهَ مَنْ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَكَرَ فِي ‏ ‏الْجَدِّ ‏ ‏شَيْئًا فَقَامَ ‏ ‏مَعْقِلُ بْنُ يَسَارٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ قَدْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِفَرِيضَةٍ فِيهَا جَدٌّ فَأَعْطَاهُ ثُلُثًا أَوْ سُدُسًا قَالَ وَمَا الْفَرِيضَةُ قَالَ لَا أَدْرِي قَالَ مَا مَنَعَكَ أَنْ تَدْرِيَ ‏","","",""],[19423,19423,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏سَأَلَ عَنْ فَرِيضَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْجَدِّ ‏ ‏فَقَامَ ‏ ‏مَعْقِلُ بْنُ يَسَارٍ الْمُزَنِيُّ ‏ ‏فَقَالَ قَضَى فِيهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَاذَا قَالَ السُّدُسَ قَالَ مَعَ مَنْ قَالَ لَا أَدْرِي قَالَ لَا دَرَيْتَ فَمَا تُغْنِي إِذًا ‏","","",""],[19424,19424,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏مُسْتَلِمُ بْنُ سَعِيدٍ الثَّقَفِيُّ ‏ ‏عَنْ ‏ ‏مَنْصُورِ بْنِ زَاذَانَ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏عَنْ ‏ ‏مَعْقِلِ بْنِ يَسَارٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعِبَادَةُ فِي الْفِتْنَةِ كَالْهِجْرَةِ إِلَيَّ ‏","","",""],[19425,19425,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَحَسَنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏رَجُلٍ هُوَ ‏ ‏الْحَسَنُ ‏ ‏إِنْ شَاءَ اللَّهُ ‏ ‏عَنْ ‏ ‏مَعْقِلِ بْنِ يَسَارٍ ‏ ‏قَالَ ‏ ‏لَمْ يَكُنْ شَيْءٌ أَحَبَّ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْخَيْلِ ثُمَّ قَالَ اللَّهُمَّ غُفْرًا لَا بَلْ النِّسَاءُ ‏","","",""],[19426,19426,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ يَعْنِي ابْنَ مُرَّةَ أَبُو الْمُعَلَّى ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏ثَقُلَ ‏ ‏مَعْقِلُ بْنُ يَسَارٍ ‏ ‏فَدَخَلَ إِلَيْهِ ‏ ‏عُبَيْدُ اللَّهِ بْنُ زِيَادٍ ‏ ‏يَعُودُهُ ‏ ‏فَقَالَ هَلْ تَعْلَمُ يَا ‏ ‏مَعْقِلُ ‏ ‏أَنِّي سَفَكْتُ دَمًا قَالَ مَا عَلِمْتُ قَالَ هَلْ تَعْلَمُ أَنِّي دَخَلْتُ فِي شَيْءٍ مِنْ أَسْعَارِ الْمُسْلِمِينَ قَالَ مَا عَلِمْتُ قَالَ أَجْلِسُونِي ثُمَّ قَالَ اسْمَعْ يَا ‏ ‏عُبَيْدَ اللَّهِ ‏ ‏حَتَّى أُحَدِّثَكَ شَيْئًا لَمْ أَسْمَعْهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّةً وَلَا مَرَّتَيْنِ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ دَخَلَ فِي شَيْءٍ مِنْ أَسْعَارِ الْمُسْلِمِينَ لِيُغْلِيَهُ عَلَيْهِمْ فَإِنَّ حَقًّا عَلَى اللَّهِ تَبَارَكَ وَتَعَالَى أَنْ يُقْعِدَهُ بِعُظْمٍ مِنْ النَّارِ يَوْمَ الْقِيَامَةِ قَالَ أَأَنْتَ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ غَيْرَ مَرَّةٍ وَلَا مَرَّتَيْنِ ‏","","",""],[19427,19427,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَعَتَّابٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏وَلَيْسَ ‏ ‏بِالنَّهْدِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَعْقِلِ بْنِ يَسَارٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْرَءُوهَا عَلَى مَوْتَاكُمْ ‏ ‏قَالَ ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏فِي حَدِيثِهِ ‏ ‏يَعْنِي ‏ ‏يس ‏","","",""],[19428,19428,"","","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ بْنُ خَلِيفَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏مَرِضَ ‏ ‏مَعْقِلُ بْنُ يَسَارٍ ‏ ‏مَرَضًا ثَقُلَ فِيهِ فَأَتَاهُ ‏ ‏ابْنُ زِيَادٍ ‏ ‏يَعُودُهُ ‏ ‏فَقَالَ إِنِّي مُحَدِّثُكَ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ اسْتُرْعِيَ رَعِيَّةً فَلَمْ يُحِطْهُمْ بِنَصِيحَةٍ لَمْ يَجِدْ رِيحَ الْجَنَّةِ وَرِيحُهَا يُوجَدُ مِنْ مَسِيرَةِ مِائَةِ عَامٍ ‏ ‏قَالَ ‏ ‏ابْنُ زِيَادٍ ‏ ‏أَلَا كُنْتَ حَدَّثْتَنِي بِهَذَا قَبْلَ الْآنَ قَالَ وَالْآنَ لَوْلَا الَّذِي أَنْتَ عَلَيْهِ لَمْ أُحَدِّثْكَ بِهِ ‏","","",""],[19429,19429,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ سِيرِينَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ قَتَادَةَ بْنِ مِلْحَانَ الْقَيْسِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُنَا بِصِيَامِ لَيَالِي الْبِيضِ ثَلَاثَ عَشْرَةَ وَأَرْبَعَ عَشْرَةَ وَخَمْسَ عَشْرَةَ وَقَالَ هِيَ كَصَوْمِ الدَّهْرِ ‏","","",""],[19430,19430,"","","‏ ‏حَدَّثَنَا ‏ ‏عَارِمٌ ‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏قَالَ وَحَدَّثَ ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ عُمَيْرٍ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏قَتَادَةَ بْنِ مِلْحَانَ ‏ ‏حِينَ حُضِرَ فَمَرَّ رَجُلٌ فِي أَقْصَى الدَّارِ قَالَ فَأَبْصَرْتُهُ فِي وَجْهِ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ‏ ‏وَكُنْتُ إِذَا رَأَيْتُهُ كَأَنَّ عَلَى وَجْهِهِ الدِّهَانَ قَالَ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَسَحَ عَلَى وَجْهِهِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ مَعِينٍ ‏ ‏وَهُرَيْمٌ أَبُو حَمْزَةَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[19431,19431,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنِي ‏ ‏أَنَسُ بْنُ سِيرِينَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏رَجُلٍ مِنْ ‏ ‏بَنِي قَيْسِ بْنِ ثَعْلَبَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَأْمُرُهُمْ بِصِيَامِ أَيَّامِ الْبِيضِ وَيَقُولُ هُنَّ صِيَامُ الشَّهْرِ ‏ ‏أَوْ قَالَ الدَّهْرِ ‏","","",""],[19432,19432,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ قَتَادَةَ بْنِ مِلْحَانَ الْقَيْسِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُنَا أَنْ نَصُومَ اللَّيَالِي الْبِيضَ ثَلَاثَ عَشْرَةَ وَأَرْبَعَ عَشْرَةَ وَخَمْسَ عَشْرَةَ وَقَالَ هُنَّ كَهَيْئَةِ الدَّهْرِ ‏","","",""],[19433,19433,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ سِيرِينَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الْمَلِكِ بْنَ الْمِنْهَالِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُنَا بِصِيَامِ أَيَّامِ الْبِيضِ الثَّلَاثَةِ وَيَقُولُ هُنَّ صِيَامُ الدَّهْرِ ‏","","",""],[19434,19434,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُطَرِّفًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَعْرَابِيٍّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ فِي رِجْلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعْلًا ‏ ‏مَخْصُوفَةً ‏","","",""],[19435,19435,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي السَّلِيلِ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏مُجِيبَةُ ‏ ‏عَجُوزٌ مِنْ ‏ ‏بِاهِلَةَ ‏ ‏عَنْ ‏ ‏أَبِيهَا ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏عَمِّهَا ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِحَاجَةٍ مَرَّةً فَقَالَ مَنْ أَنْتَ قَالَ ‏ ‏أَوَ مَا تَعْرِفُنِي قَالَ وَمَنْ أَنْتَ قَالَ أَنَا ‏ ‏الْبَاهِلِيُّ الَّذِي أَتَيْتُكَ عَامَ أَوَّلٍ قَالَ فَإِنَّكَ أَتَيْتَنِي وَجِسْمُكَ وَلَوْنُكَ وَهَيْئَتُك حَسَنَةٌ فَمَا بَلَغَ بِكَ مَا أَرَى فَقَالَ إِنِّي وَاللَّهِ مَا أَفْطَرْتُ بَعْدَكَ إِلَّا لَيْلًا قَالَ مَنْ أَمَرَكَ أَنْ تُعَذِّبَ نَفْسَكَ مَنْ أَمَرَكَ أَنْ تُعَذِّبَ نَفْسَكَ مَنْ أَمَرَكَ أَنْ تُعَذِّبَ نَفْسَكَ ثَلَاثَ مَرَّاتٍ ‏ ‏صُمْ شَهْرَ الصَّبْرِ رَمَضَانَ قُلْتُ إِنِّي أَجِدُ قُوَّةً وَإِنِّي أُحِبُّ أَنْ تَزِيدَنِي فَقَالَ فَصُمْ يَوْمًا مِنْ الشَّهْرِ قُلْتُ إِنِّي أَجِدُ قُوَّةً وَإِنِّي أُحِبُّ أَنْ تَزِيدَنِي قَالَ فَيَوْمَيْنِ مِنْ الشَّهْرِ قُلْتُ إِنِّي أَجِدُ قُوَّةً وَإِنِّي أُحِبُّ أَنْ تَزِيدَنِي قَالَ وَمَا ‏ ‏تَبْغِي ‏ ‏عَنْ شَهْرِ الصَّبْرِ وَيَوْمَيْنِ فِي الشَّهْرِ قَالَ قُلْتُ إِنِّي أَجِدُ قُوَّةً وَإِنِّي أُحِبُّ أَنْ تَزِيدَنِي قَالَ فَثَلَاثَةَ أَيَّامٍ مِنْ الشَّهْرِ قَالَ ‏ ‏وَأَلْحَمَ ‏ ‏عِنْدَ الثَّالِثَةِ فَمَا كَادَ قُلْتُ إِنِّي أَجِدُ قُوَّةً وَإِنِّي أُحِبُّ أَنْ تَزِيدَنِي قَالَ فَمِنْ الْحُرُمِ وَأَفْطِرْ ‏","","",""],[19436,19436,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ الثَّقَفِيِّ ‏ ‏أَنَّ رَجُلًا أَعْوَرَ مِنْ ‏ ‏ثَقِيفٍ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏كَانَ يُقَالُ لَهُ مَعْرُوفٌ أَيْ ‏ ‏يُثْنَى عَلَيْهِ خَيْرًا يُقَالُ لَهُ ‏ ‏زُهَيْرُ بْنُ عُثْمَانَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْوَلِيمَةُ ‏ ‏حَقٌّ وَالْيَوْمُ الثَّانِي مَعْرُوفٌ وَالْيَوْمُ الثَّالِثُ سُمْعَةٌ ‏ ‏وَرِيَاءٌ ‏","","",""],[19437,19437,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ الثَّقَفِيِّ ‏ ‏عَنْ ‏ ‏رَجُلٍ أَعْوَرَ مِنْ ‏ ‏ثَقِيفٍ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏وَكَانَ يُقَالُ لَهُ مَعْرُوفٌ إِنْ لَمْ يَكُنْ اسْمُهُ ‏ ‏زُهَيْرَ بْنَ عُثْمَانَ ‏ ‏فَلَا أَدْرِي مَا اسْمُهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْوَلِيمَةُ ‏ ‏أَوَّلَ يَوْمٍ حَقٌّ وَالثَّانِي ‏ ‏مَعْرُوفٌ وَالْيَوْمَ الثَّالِثَ ‏ ‏سُمْعَةٌ ‏ ‏وَرِيَاءٌ ‏","","",""],[19438,19438,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَبُو قِلَابَةَ ‏ ‏حَدَّثَنِي ‏ ‏بِهَذَا الْحَدِيثِ ثُمَّ قَالَ لِي هَلْ لَكَ فِي ‏ ‏الَّذِي ‏ ‏حَدَّثَنِيهِ قَالَ فَدَلَّنِي عَلَيْهِ فَأَتَيْتُهُ ‏ ‏فَقَالَ حَدَّثَنِي ‏ ‏قَرِيبٌ لِي يُقَالُ لَهُ ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي إِبِلٍ لِجَارٍ لِي أُخِذَتْ فَوَافَقْتُهُ وَهُوَ يَأْكُلُ فَدَعَانِي إِلَى طَعَامِهِ فَقُلْتُ إِنِّي صَائِمٌ فَقَالَ ادْنُ أَوْ قَالَ هَلُمَّ أُخْبِرْكَ عَنْ ذَلِكَ إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى ‏ ‏وَضَعَ عَنْ الْمُسَافِرِ الصَّوْمَ ‏ ‏وَشَطْرَ ‏ ‏الصَّلَاةِ وَعَنْ الْحُبْلَى وَالْمُرْضِعِ قَالَ كَانَ بَعْدَ ذَلِكَ يَتَلَهَّفُ يَقُولُ أَلَا أَكُونُ أَكَلْتُ مِنْ طَعَامِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ دَعَانِي إِلَيْهِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَوَادَةَ الْقُشَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَحَدُ ‏ ‏بَنِي كَعْبٍ ‏ ‏أَخُو ‏ ‏بَنِي قُشَيْرٍ ‏ ‏قَالَ ‏ ‏أَغَارَتْ ‏ ‏عَلَيْنَا خَيْلُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَانْطَلَقْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَانْتَهَيْتُ إِلَيْهِ وَهُوَ يَأْكُلُ فَقَالَ ‏ ‏لِيَ ‏ ‏ادْنُ ‏ ‏فَكُلْ فَقُلْتُ إِنِّي صَائِمٌ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[19439,19439,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏قَتَادَةُ ‏ ‏وَبَهْزٌ ‏ ‏قَالَ وَحَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زُرَارَةَ بْنَ أَوْفَى ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أُبَيِّ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ أَدْرَكَ وَالِدَيْهِ أَوْ أَحَدَهُمَا ثُمَّ دَخَلَ النَّارَ مِنْ بَعْدِ ذَلِكَ فَأَبْعَدَهُ اللَّهُ وَأَسْحَقَهُ ‏","","",""],[19440,19440,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ أَبِي الْمِنْهَالِ بْنِ سَلَمَةَ الْخُزَاعِيِّ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِأَسْلَمَ ‏ ‏صُومُوا الْيَوْمَ فَقَالُوا إِنَّا قَدْ أَكَلْنَا قَالَ صُومُوا بَقِيَّةَ يَوْمِكُمْ ‏ ‏يَعْنِي ‏ ‏يَوْمَ عَاشُورَاءَ ‏","","",""],[19441,19441,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَلِيَّ بْنَ زَيْدٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ قَوْمِهِ يُقَالُ لَهُ ‏ ‏مَالِكٌ ‏ ‏أَوْ ‏ ‏ابْنُ مَالِكٍ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَيُّمَا مُسْلِمٍ ضَمَّ يَتِيمًا بَيْنَ أَبَوَيْنِ مُسْلِمَيْنِ إِلَى طَعَامِهِ وَشَرَابِهِ حَتَّى يَسْتَغْنِيَ وَجَبَتْ لَهُ الْجَنَّةُ ‏ ‏الْبَتَّةَ ‏ ‏وَأَيُّمَا مُسْلِمٍ أَعْتَقَ رَقَبَةً أَوْ رَجُلًا مُسْلِمًا كَانَتْ فِكَاكَهُ مِنْ النَّارِ وَمَنْ أَدْرَكَ وَالِدَيْهِ أَوْ أَحَدَهُمَا فَدَخَلَ النَّارَ فَأَبْعَدَهُ اللَّهُ ‏","","",""],[19442,19442,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏أَخْبَرَنَا عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ الْحَارِثِ ‏ ‏رَجُلٍ مِنْهُمْ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ ضَمَّ يَتِيمًا بَيْنَ أَبَوَيْنِ مُسْلِمَيْنِ إِلَى طَعَامِهِ وَشَرَابِهِ حَتَّى يَسْتَغْنِيَ عَنْهُ وَجَبَتْ لَهُ الْجَنَّةُ ‏ ‏الْبَتَّةَ ‏ ‏وَمَنْ أَعْتَقَ امْرَأً مُسْلِمًا كَانَ فِكَاكَهُ مِنْ النَّارِ ‏ ‏يُجْزَى بِكُلِّ عُضْوٍ مِنْهُ عُضْوًا مِنْهُ ‏","","",""],[19443,19443,"","","‏ ‏سَنَةَ ثَمَانٍ وَعِشْرِينَ وَمِئَتَيْنِ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرُ بْنُ حَبِيبٍ الْجَرْمِيُّ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ سَلِمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُمْ وَفَدُوا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا أَرَادُوا أَنْ يَنْصَرِفُوا قَالُوا يَا رَسُولَ اللَّهِ ‏ ‏مَنْ يَؤُمُّنَا قَالَ أَكْثَرُكُمْ جَمْعًا لِلْقُرْآنِ ‏ ‏أَوْ أَخْذًا لِلْقُرْآنِ ‏ ‏قَالَ فَلَمْ يَكُنْ أَحَدٌ مِنْ الْقَوْمِ جَمَعَ مِنْ الْقُرْآنِ مَا جَمَعْتُ قَالَ فَقَدَّمُونِي وَأَنَا غُلَامٌ فَكُنْتُ أَؤُمُّهُمْ وَعَلَيَّ ‏ ‏شَمْلَةٌ ‏ ‏لِي قَالَ فَمَا شَهِدْتُ مَجْمَعًا مِنْ ‏ ‏جَرْمٍ ‏ ‏إِلَّا كُنْتُ إِمَامَهُمْ وَأُصَلِّي عَلَى ‏ ‏جَنَائِزِهِمْ إِلَى يَوْمِي هَذَا ‏","","",""],[19444,19444,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سَلِمَةَ ‏ ‏قَالَ ‏ ‏كُنَّا عَلَى حَاضِرٍ فَكَانَ الرُّكْبَانُ ‏ ‏وَقَالَ ‏ ‏إِسْمَاعِيلُ ‏ ‏مَرَّةً النَّاسُ ‏ ‏يَمُرُّونَ بِنَا رَاجِعِينَ مِنْ عِنْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَدْنُو مِنْهُمْ فَأَسْمَعُ حَتَّى حَفِظْتُ قُرْآنًا وَكَانَ النَّاسُ يَنْتَظِرُونَ بِإِسْلَامِهِمْ فَتْحَ ‏ ‏مَكَّةَ ‏ ‏فَلَمَّا فُتِحَتْ جَعَلَ الرَّجُلُ يَأْتِيهِ فَيَقُولُ يَا رَسُولَ اللَّهِ أَنَا وَافِدُ بَنِي فُلَانٍ وَجِئْتُكَ بِإِسْلَامِهِمْ فَانْطَلَقَ ‏ ‏أَبِي ‏ ‏بِإِسْلَامِ قَوْمِهِ فَرَجَعَ إِلَيْهِمْ فَقَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدِّمُوا أَكْثَرَكُمْ قُرْآنًا قَالَ فَنَظَرُوا ‏ ‏وَأَنَا لَعَلَى حِوَاءٍ عَظِيمٍ ‏ ‏فَمَا وَجَدُوا فِيهِمْ أَحَدًا أَكْثَرَ قُرْآنًا مِنِّي فَقَدَّمُونِي وَأَنَا غُلَامٌ فَصَلَّيْتُ بِهِمْ وَعَلَيَّ بُرْدَةٌ وَكُنْتُ إِذَا رَكَعْتُ أَوْ سَجَدْتُ قَلَصَتْ فَتَبْدُو عَوْرَتِي فَلَمَّا صَلَّيْنَا تَقُولُ عَجُوزٌ لَنَا ‏ ‏دَهْرِيَّةٌ غَطُّوا عَنَّا ‏ ‏اسْتَ ‏ ‏قَارِئِكُمْ قَالَ فَقَطَعُوا لِي قَمِيصًا فَذَكَرَ أَنَّهُ فَرِحَ بِهِ فَرَحًا شَدِيدًا ‏","","",""],[19445,19445,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏قَالَ ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏أَخْبَرَنِي عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سَلِمَةَ ‏ ‏قَالَ ‏ ‏كَانَتْ تَأْتِينَا ‏ ‏الرُّكْبَانُ ‏ ‏مِنْ قِبَلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَسْتَقْرِئُهُمْ فَيُحَدِّثُونَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِيَؤُمَّكُمْ أَكْثَرُكُمْ قُرْآنًا ‏","","",""],[19446,19446,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الْمَجِيدِ أَبُو عَمْرٍو ‏ ‏حَدَّثَنِي ‏ ‏الْعَدَّاءُ بْنُ خَالِدِ بْنِ هَوْذَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ النَّاسَ يَوْمَ ‏ ‏عَرَفَةَ ‏ ‏عَلَى بَعِيرٍ قَائِمًا فِي ‏ ‏الرِّكَابَيْنِ ‏","","",""],[19447,19447,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ إِبْرَاهِيمَ الْيَشْكُرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شَيْخٌ كَبِيرٌ مِنْ ‏ ‏بَنِي عُقَيْلٍ ‏ ‏يُقَالُ لَهُ ‏ ‏عَبْدُ الْمَجِيدِ الْعُقَيْلِيُّ ‏ ‏قَالَ ‏ ‏انْطَلَقْنَا حُجَّاجًا ‏ ‏لَيَالِيَ خَرَجَ ‏ ‏يَزِيدُ بْنُ الْمُهَلَّبِ ‏ ‏وَقَدْ ذُكِرَ لَنَا أَنَّ مَاءً ‏ ‏بِالْعَالِيَةِ ‏ ‏يُقَالُ لَهُ ‏ ‏الزُّجَيْجُ ‏ ‏فَلَمَّا قَضَيْنَا مَنَاسِكَنَا جِئْنَا حَتَّى أَتَيْنَا ‏ ‏الزُّجَيْجَ ‏ ‏فَأَنَخْنَا رَوَاحِلَنَا قَالَ فَانْطَلَقْنَا حَتَّى أَتَيْنَا عَلَى بِئْرٍ عَلَيْهِ أَشْيَاخٌ ‏ ‏مُخَضَّبُونَ ‏ ‏يَتَحَدَّثُونَ قَالَ قُلْنَا هَذَا الَّذِي صَحِبَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيْنَ بَيْتُهُ قَالُوا نَعَمْ صَحِبَهُ وَهَذَاكَ بَيْتُهُ فَانْطَلَقْنَا حَتَّى أَتَيْنَا الْبَيْتَ فَسَلَّمْنَا قَالَ فَأَذِنَ لَنَا فَإِذَا هُوَ شَيْخٌ كَبِيرٌ مُضْطَجِعٌ يُقَالُ لَهُ ‏ ‏الْعَدَّاءُ بْنُ خَالِدٍ الْكِلَابِيُّ ‏ ‏قُلْتُ أَنْتَ الَّذِي صَحِبْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ وَلَوْلَا أَنَّهُ اللَّيْلُ لَأَقْرَأْتُكُمْ كِتَابَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَيَّ قَالَ فَمَنْ أَنْتُمْ قُلْنَا مِنْ أَهْلِ ‏ ‏الْبَصْرَةِ ‏ ‏قَالَ مَرْحَبًا بِكُمْ مَا فَعَلَ ‏ ‏يَزِيدُ بْنُ الْمُهَلَّبِ ‏ ‏قُلْنَا هُوَ هُنَاكَ يَدْعُو إِلَى كِتَابِ اللَّهِ تَبَارَكَ وَتَعَالَى وَإِلَى سُنَّةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِيمَا هُوَ مِنْ ذَاكَ فِيمَا هُوَ مِنْ ذَاكَ قَالَ قُلْتُ أَيًّا نَتَّبِعُ هَؤُلَاءِ أَوْ هَؤُلَاءِ ‏ ‏يَعْنِي أَهْلَ ‏ ‏الشَّامِ ‏ ‏أَوْ ‏ ‏يَزِيدَ ‏ ‏قَالَ إِنْ تَقْعُدُوا تُفْلِحُوا وَتَرْشُدُوا إِنْ تَقْعُدُوا تُفْلِحُوا وَتَرْشُدُوا ‏ ‏لَا أَعْلَمُهُ إِلَّا قَالَ ثَلَاثَ مَرَّاتٍ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏عَرَفَةَ ‏ ‏وَهُوَ قَائِمٌ فِي ‏ ‏الرِّكَابَيْنِ ‏ ‏يُنَادِي بِأَعْلَى صَوْتِهِ يَا أَيُّهَا النَّاسُ أَيُّ يَوْمِكُمْ هَذَا قَالُوا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ فَأَيُّ شَهْرٍ شَهْرُكُمْ هَذَا قَالُوا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ فَأَيُّ بَلَدٍ بَلَدُكُمْ هَذَا قَالُوا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ ‏ ‏يَوْمُكُمْ يَوْمٌ حَرَامٌ وَشَهْرُكُمْ شَهْرٌ حَرَامٌ وَبَلَدُكُمْ بَلَدٌ حَرَامٌ قَالَ فَقَالَ أَلَا إِنَّ دِمَاءَكُمْ وَأَمْوَالَكُمْ عَلَيْكُمْ حَرَامٌ كَحُرْمَةِ يَوْمِكُمْ هَذَا فِي شَهْرِكُمْ هَذَا فِي بَلَدِكُمْ هَذَا إِلَى يَوْمِ تَلْقَوْنَ رَبَّكُمْ تَبَارَكَ وَتَعَالَى فَيَسْأَلُكُمْ عَنْ أَعْمَالِكُمْ قَالَ ثُمَّ رَفَعَ يَدَيْهِ إِلَى السَّمَاءِ فَقَالَ اللَّهُمَّ اشْهَدْ عَلَيْهِمْ اللَّهُمَّ اشْهَدْ عَلَيْهِمْ ‏ ‏ذَكَرَ مِرَارًا فَلَا أَدْرِي كَمْ ذَكَرَهُ ‏","","",""],[19448,19448,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ رَاشِدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏حَدَّثَنَا ‏ ‏أَحْمَرُ صَاحِبُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنْ كُنَّا ‏ ‏لَنَأْوِي لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِمَّا ‏ ‏يُجَافِي ‏ ‏بِيَدَيْهِ عَنْ جَنْبَيْهِ إِذَا سَجَدَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ رَاشِدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏حَدَّثَنِي ‏ ‏أَحْمَرُ صَاحِبُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُنَّا لَيَأْوِي لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِمَّا يُجَافِي بِيَدَيْهِ عَنْ جَنْبَيْهِ إِذَا سَجَدَ ‏","","",""],[19449,19449,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ يَسَارٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ صُحَارٍ الْعَبْدِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏إِنِّي رَجُلٌ ‏ ‏مِسْقَامٌ ‏ ‏فَأْذَنْ لِي فِي ‏ ‏جَرِيرَةٍ ‏ ‏أَنْتَبِذُ فِيهَا قَالَ فَأَذِنَ لَهُ فِيهَا ‏","","",""],[19450,19450,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْعَلَاءِ بْنِ الشِّخِّيرِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ صُحَارٍ الْعَبْدِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يُخْسَفَ بِقَبَائِلَ حَتَّى يُقَالَ مَنْ بَقِيَ مِنْ بَنِي فُلَانٍ ‏ ‏فَعَرَفْتُ أَنَّهُ ‏ ‏يَعْنِي ‏ ‏الْعَرَبَ ‏ ‏لِأَنَّ ‏ ‏الْعَجَمَ ‏ ‏إِنَّمَا تُنْسَبُ إِلَى قُرَاهَا ‏","","",""],[19451,19451,"","","‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمُشْمَعِلُّ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ سُلَيْمٍ الْمُزَنِيُّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏رَافِعَ بْنَ عَمْرٍو الْمُزَنِيَّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ وَأَنَا وَصِيفٌ يَقُولُ ‏ ‏الْعَجْوَةُ وَالشَّجَرَةُ مِنْ الْجَنَّةِ ‏","","",""],[19452,19452,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَأَبُو النَّضْرِ ‏ ‏وَعَفَّانُ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الصَّامِتِ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِنْ بَعْدِي مِنْ أُمَّتِي قَوْمًا يَقْرَءُونَ الْقُرْآنَ لَا يُجَاوِزُ حَلَاقِيمَهُمْ يَخْرُجُونَ مِنْ الدِّينِ كَمَا يَخْرُجُ السَّهْمُ مِنْ الرَّمِيَّةِ ثُمَّ لَا يَعُودُونَ فِيهِ شَرُّ الْخَلْقِ وَالْخَلِيقَةِ ‏ ‏قَالَ ‏ ‏ابْنُ الصَّامِتِ ‏ ‏فَلَقِيتُ ‏ ‏رَافِعًا ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏أَخَا ‏ ‏الْحَكَمِ بْنِ عَمْرٍو ‏ ‏فَحَدَّثْتُهُ هَذَا الْحَدِيثَ قَالَ وَأَنَا أَيْضًا قَدْ سَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[19453,19453,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ أَبِي الْحَكَمِ الْغِفَارِيَّ ‏ ‏يَقُولُ حَدَّثَتْنِي ‏ ‏جَدَّتِي ‏ ‏عَنْ ‏ ‏عَمِّ أَبِيهَا ‏ ‏رَافِعِ بْنِ عَمْرٍو الْغِفَارِيِّ ‏ ‏قَالَ ‏ ‏كُنْتُ وَأَنَا غُلَامٌ أَرْمِي نَخْلًا ‏ ‏لِلْأَنْصَارِ ‏ ‏فَأُتِيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقِيلَ إِنَّ هَاهُنَا غُلَامًا يَرْمِي نَخْلَنَا فَأُتِيَ بِي إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا غُلَامُ لِمَ تَرْمِي النَّخْلَ قَالَ قُلْتُ آكُلُ قَالَ ‏ ‏فَلَا تَرْمِ النَّخْلَ وَكُلْ مَا يَسْقُطُ فِي أَسَافِلِهَا ثُمَّ مَسَحَ رَأْسِي وَقَالَ اللَّهُمَّ أَشْبِعْ بَطْنَهُ ‏","","",""],[19454,19454,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُشْمَعِلُّ بْنُ عَمْرٍو الْمُزَنِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ سُلَيْمٍ الْمُزَنِيُّ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ عَمْرٍو الْمُزَنِيِّ ‏ ‏يَقُولُ قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْعَجْوَةُ وَالصَّخْرَةُ ‏ ‏أَوْ قَالَ الْعَجْوَةُ وَالشَّجَرَةُ فِي الْجَنَّةِ شَكَّ ‏ ‏الْمُشْمَعِلُّ ‏","","",""],[19455,19455,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏الْمُشْمَعِلُّ بْنُ إِيَاسٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ سُلَيْمٍ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏رَافِعَ بْنَ عَمْرٍو الْمُزَنِيَّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْعَجْوَةُ وَالصَّخْرَةُ مِنْ الْجَنَّةِ ‏","","",""],[19456,19456,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الصَّامِتِ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ بَعْدِي مِنْ أُمَّتِي قَوْمًا يَقْرَءُونَ الْقُرْآنَ لَا يُجَاوِزُ حَلَاقِيمَهُمْ يَخْرُجُونَ مِنْ الدِّينِ كَمَا يَخْرُجُ السَّهْمُ مِنْ ‏ ‏الرَّمِيَّةِ ‏ ‏ثُمَّ لَا يَعُودُونَ إِلَيْهِ شَرُّ الْخَلْقِ وَالْخَلِيقَةِ ‏ ‏قَالَ ‏ ‏ابْنُ الصَّامِتِ ‏ ‏فَلَقِيتُ ‏ ‏رَافِعًا ‏ ‏فَحَدَّثْتُهُ فَقَالَ ‏ ‏وَأَنَا أَيْضًا قَدْ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[19457,19457,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏كَهْمَسٌ ‏ ‏وَيَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏كَهْمَسٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ شَقِيقٍ ‏ ‏قَالَ ‏ ‏مِحْجَنُ بْنُ الْأَدْرَعِ ‏ ‏بَعَثَنِي نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَاجَةٍ ثُمَّ عَرَضَ لِي وَأَنَا خَارِجٌ مِنْ طَرِيقٍ مِنْ طُرُقِ ‏ ‏الْمَدِينَةِ ‏ ‏قَالَ فَانْطَلَقْتُ مَعَهُ حَتَّى صَعِدْنَا ‏ ‏أُحُدًا ‏ ‏فَأَقْبَلَ عَلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَقَالَ وَيْلُ أُمِّهَا قَرْيَةً يَوْمَ يَدَعُهَا أَهْلُهَا ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏كَأَيْنَعِ مَا تَكُونُ ‏ ‏قَالَ قُلْتُ يَا نَبِيَّ اللَّهِ ‏ ‏مَنْ يَأْكُلُ ثَمَرَتَهَا قَالَ عَافِيَةُ الطَّيْرِ وَالسِّبَاعُ قَالَ وَلَا يَدْخُلُهَا ‏ ‏الدَّجَّالُ ‏ ‏كُلَّمَا أَرَادَ أَنْ يَدْخُلَهَا ‏ ‏تَلَقَّاهُ ‏ ‏بِكُلِّ ‏ ‏نَقْبٍ ‏ ‏مِنْهَا مَلَكٌ مُصْلِتًا قَالَ ثُمَّ أَقْبَلْنَا حَتَّى إِذَا كُنَّا بِبَابِ الْمَسْجِدِ قَالَ إِذَا رَجُلٌ ‏ ‏يُصَلِّي قَالَ أَتَقُولُهُ صَادِقًا قَالَ قُلْتُ يَا نَبِيَّ اللَّهِ هَذَا فُلَانٌ وَهَذَا مِنْ أَحْسَنِ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏أَوْ قَالَ أَكْثَرِ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏صَلَاةً قَالَ لَا تُسْمِعْهُ فَتُهْلِكَهُ مَرَّتَيْنِ أَوْ ثَلَاثًا إِنَّكُمْ أُمَّةٌ أُرِيدَ بِكُمْ الْيُسْرُ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ شَقِيقٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏رَجَاءِ بْنِ أَبِي رَجَاءٍ الْبَاهِلِيِّ ‏ ‏عَنْ ‏ ‏مِحْجَنٍ ‏ ‏رَجُلٍ مِنْ ‏ ‏أَسْلَمَ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[19458,19458,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏رَجَاءِ بْنِ أَبِي رَجَاءٍ الْبَاهِلِيِّ ‏ ‏عَنْ ‏ ‏مِحْجَنٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏وَهُوَ ‏ ‏ابْنُ الْأَدْرَعِ ‏ ‏قَالَ ‏ ‏وَحَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنِ ‏ ‏الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏مِحْجَنِ بْنِ الْأَدْرَعِ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏رَجَاءٌ ‏ ‏أَقْبَلْتُ مَعَ ‏ ‏مِحْجَنٍ ‏ ‏ذَاتَ يَوْمٍ حَتَّى إِذَا انْتَهَيْنَا إِلَى مَسْجِدِ ‏ ‏الْبَصْرَةِ ‏ ‏فَوَجَدْنَا ‏ ‏بُرَيْدَةَ الْأَسْلَمِيَّ ‏ ‏عَلَى بَابٍ مِنْ أَبْوَابِ الْمَسْجِدِ جَالِسًا قَالَ وَكَانَ فِي الْمَسْجِدِ رَجُلٌ يُقَالُ لَهُ ‏ ‏سُكْبَةُ ‏ ‏يُطِيلُ الصَّلَاةَ فَلَمَّا انْتَهَيْنَا إِلَى بَابِ الْمَسْجِدِ وَعَلَيْهِ ‏ ‏بُرَيْدَةُ ‏ ‏قَالَ وَكَانَ ‏ ‏بُرَيْدَةُ ‏ ‏صَاحِبَ مُزَاحَاتٍ قَالَ يَا ‏ ‏مِحْجَنُ ‏ ‏أَلَا تُصَلِّي كَمَا ‏ ‏يُصَلِّي ‏ ‏سُكْبَةُ ‏ ‏قَالَ فَلَمْ يَرُدَّ عَلَيْهِ ‏ ‏مِحْجَنٌ ‏ ‏شَيْئًا وَرَجَعَ قَالَ وَقَالَ لِي ‏ ‏مِحْجَنٌ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَذَ بِيَدِي فَانْطَلَقَ يَمْشِي حَتَّى صَعِدَ ‏ ‏أُحُدًا ‏ ‏فَأَشْرَفَ عَلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَقَالَ ‏ ‏وَيْلُ أُمِّهَا مِنْ قَرْيَةٍ يَتْرُكُهَا أَهْلُهَا ‏ ‏كَأَعْمَرِ مَا تَكُونُ يَأْتِيهَا ‏ ‏الدَّجَّالُ ‏ ‏فَيَجِدُ عَلَى كُلِّ بَابٍ مِنْ أَبْوَابِهَا مَلَكًا مُصْلِتًا فَلَا يَدْخُلُهَا قَالَ ثُمَّ انْحَدَرَ حَتَّى إِذَا كُنَّا بِسُدَّةِ الْمَسْجِدِ رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلًا ‏ ‏يُصَلِّي فِي الْمَسْجِدِ وَيَسْجُدُ وَيَرْكَعُ وَيَسْجُدُ وَيَرْكَعُ قَالَ فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ هَذَا قَالَ فَأَخَذْتُ ‏ ‏أُطْرِيهِ ‏ ‏لَهُ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ هَذَا فُلَانٌ وَهَذَا وَهَذَا قَالَ اسْكُتْ لَا تُسْمِعْهُ فَتُهْلِكَهُ قَالَ ثُمَّ انْطَلَقَ يَمْشِي حَتَّى إِذَا كُنَّا عِنْدَ حُجْرَةٍ لَكِنَّهُ رَفَضَ يَدِي ثُمَّ قَالَ إِنَّ خَيْرَ دِينِكُمْ أَيْسَرُهُ إِنَّ خَيْرَ دِينِكُمْ أَيْسَرُهُ إِنَّ خَيْرَ دِينِكُمْ أَيْسَرُهُ ‏","","",""],[19459,19459,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏وَيَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏عَنِ ‏ ‏الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ ‏ ‏خَرَجْتُ مِنْ أَهْلِي أُرِيدُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِذَا أَنَا بِهِ قَائِمٌ وَرَجُلٌ مَعَهُ مُقْبِلٌ عَلَيْهِ فَظَنَنْتُ أَنَّ لَهُمَا حَاجَةً قَالَ فَقَالَ الْأَنْصَارِيُّ وَاللَّهِ لَقَدْ قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى جَعَلْتُ ‏ ‏أَرْثِي ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ طُولِ الْقِيَامِ فَلَمَّا انْصَرَفَ قُلْتُ يَا رَسُولَ اللَّهِ لَقَدْ قَامَ بِكَ الرَّجُلُ حَتَّى جَعَلْتُ ‏ ‏أَرْثِي ‏ ‏لَكَ مِنْ طُولِ الْقِيَامِ قَالَ وَلَقَدْ رَأَيْتُهُ قُلْتُ نَعَمْ قَالَ أَتَدْرِي مَنْ هُوَ قُلْتُ لَا قَالَ ذَاكَ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏مَا زَالَ يُوصِينِي بِالْجَارِ حَتَّى ظَنَنْتُ أَنَّهُ سَيُوَرِّثُهُ ثُمَّ قَالَ أَمَا إِنَّكَ لَوْ سَلَّمْتَ عَلَيْهِ رَدَّ عَلَيْكَ السَّلَامَ ‏","","",""],[19460,19460,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏بُدَيْلٍ الْعُقَيْلِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ شَقِيقٍ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏مَنْ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏بِوَادِي الْقُرَى ‏ ‏وَهُوَ عَلَى فَرَسِهِ فَسَأَلَهُ رَجُلٌ مِنْ ‏ ‏بُلْقِينَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ هَؤُلَاءِ قَالَ هَؤُلَاءِ الْمَغْضُوبُ عَلَيْهِمْ وَأَشَارَ إِلَى ‏ ‏الْيَهُودِ ‏ ‏قَالَ فَمَنْ هَؤُلَاءِ قَالَ هَؤُلَاءِ الضَّالِّينَ ‏ ‏يَعْنِي ‏ ‏النَّصَارَى ‏ ‏قَالَ وَجَاءَهُ رَجُلٌ فَقَالَ اسْتُشْهِدَ مَوْلَاكَ ‏ ‏أَوْ قَالَ غُلَامُكَ ‏ ‏فُلَانٌ ‏ ‏فَقَالَ ‏ ‏بَلْ يُجَرُّ إِلَى النَّارِ فِي عَبَاءَةٍ ‏ ‏غَلَّهَا ‏","","",""],[19461,19461,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏مُرَّةَ الْبَهْزِيِّ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏بَهْزٌ ‏ ‏فِي حَدِيثِهِ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَهِيجُ ‏ ‏فِتْنَةٌ ‏ ‏كَالصَّيَاصِي ‏ ‏فَهَذَا وَمَنْ مَعَهُ عَلَى الْحَقِّ قَالَ فَذَهَبْتُ فَأَخَذْتُ بِمَجَامِعِ ثَوْبِهِ فَإِذَا هُوَ ‏ ‏عُثْمَانُ بْنُ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏","","",""],[19462,19462,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏كَهْمَسٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ شَقِيقٍ ‏ ‏حَدَّثَنَا ‏ ‏هَرَمِيُّ بْنُ الْحَارِثِ ‏ ‏وَأُسَامَةُ بْنُ خُرَيْمٍ ‏ ‏وَكَانَا يُغَازِيَانِ فَحَدَّثَانِي حَدِيثًا وَلَا يَشْعُرُ كُلُّ وَاحِدٍ مِنْهُمَا أَنَّ صَاحِبَهُ حَدَّثَنِيهِ ‏ ‏عَنْ ‏ ‏مُرَّةَ الْبَهْزِيِّ ‏ ‏قَالَ ‏ ‏بَيْنَمَا نَحْنُ مَعَ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي طَرِيقٍ مِنْ طُرُقِ ‏ ‏الْمَدِينَةِ ‏ ‏فَقَالَ ‏ ‏كَيْفَ فِي ‏ ‏فِتْنَةٍ ‏ ‏تَثُورُ فِي ‏ ‏أَقْطَارِ ‏ ‏الْأَرْضِ كَأَنَّهَا ‏ ‏صَيَاصِي ‏ ‏بَقَرٍ قَالُوا نَصْنَعُ مَاذَا يَا نَبِيَّ اللَّهِ قَالَ عَلَيْكُمْ هَذَا وَأَصْحَابَهُ أَوْ اتَّبِعُوا هَذَا وَأَصْحَابَهُ قَالَ فَأَسْرَعْتُ حَتَّى عَطَفْتُ عَلَى الرَّجُلِ فَقُلْتُ هَذَا يَا نَبِيَّ اللَّهِ قَالَ هَذَا فَإِذَا هُوَ ‏ ‏عُثْمَانُ بْنُ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏","","",""],[19463,19463,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏كَهْمَسُ بْنُ الْحَسَنِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ شَقِيقٍ ‏ ‏حَدَّثَنِي ‏ ‏رَجُلٌ مِنْ ‏ ‏عَنَزَةَ ‏ ‏يُقَالُ لَهُ ‏ ‏زَائِدَةُ ‏ ‏أَوْ ‏ ‏مَزِيدَةُ بْنُ حَوَالَةَ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ مِنْ أَسْفَارِهِ فَنَزَلَ النَّاسُ مَنْزِلًا وَنَزَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ظِلِّ دَوْحَةٍ فَرَآنِي وَأَنَا مُقْبِلٌ مِنْ حَاجَةٍ لِي وَلَيْسَ غَيْرُهُ وَغَيْرُ كَاتِبِهِ فَقَالَ أَنَكْتُبُكَ يَا ‏ ‏ابْنَ حَوَالَةَ ‏ ‏قُلْتُ عَلَامَ يَا رَسُولَ اللَّهِ قَالَ فَلَهَا عَنِّي وَأَقْبَلَ عَلَى الْكَاتِبِ قَالَ ثُمَّ دَنَوْتُ دُونَ ذَلِكَ قَالَ فَقَالَ أَنَكْتُبُكَ يَا ‏ ‏ابْنَ حَوَالَةَ ‏ ‏قُلْتُ عَلَامَ يَا رَسُولَ اللَّهِ قَالَ فَلَهَا عَنِّي وَأَقْبَلَ عَلَى الْكَاتِبِ قَالَ ثُمَّ جِئْتُ فَقُمْتُ عَلَيْهِمَا فَإِذَا فِي صَدْرِ الْكِتَابِ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏فَظَنَنْتُ أَنَّهُمَا لَنْ يُكْتَبَا إِلَّا فِي خَيْرٍ فَقَالَ أَنَكْتُبُكَ يَا ‏ ‏ابْنَ حَوَالَةَ ‏ ‏فَقُلْتُ نَعَمْ يَا نَبِيَّ اللَّهِ فَقَالَ يَا ‏ ‏ابْنَ حَوَالَةَ ‏ ‏كَيْفَ تَصْنَعُ فِي ‏ ‏فِتْنَةٍ ‏ ‏تَثُورُ فِي ‏ ‏أَقْطَارِ ‏ ‏الْأَرْضِ كَأَنَّهَا ‏ ‏صَيَاصِي ‏ ‏بَقَرٍ قَالَ قُلْتُ أَصْنَعُ مَاذَا يَا رَسُولَ اللَّهِ قَالَ عَلَيْكَ ‏ ‏بِالشَّامِ ‏ ‏ثُمَّ قَالَ كَيْفَ تَصْنَعُ فِي ‏ ‏فِتْنَةٍ ‏ ‏كَأَنَّ الْأُولَى فِيهَا نَفْجَةُ أَرْنَبٍ ‏ ‏قَالَ فَلَا أَدْرِي كَيْفَ قَالَ فِي الْآخِرَةِ وَلَأَنْ أَكُونَ عَلِمْتُ كَيْفَ قَالَ فِي الْآخِرَةِ أَحَبُّ إِلَيَّ مِنْ كَذَا وَكَذَا ‏","","",""],[19464,19464,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ لَقِيطٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ حَوَالَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ نَجَا مِنْ ثَلَاثٍ فَقَدْ نَجَا ثَلَاثَ مَرَّاتٍ مَوْتِي ‏ ‏وَالدَّجَّالِ ‏ ‏وَقَتْلِ خَلِيفَةٍ مُصْطَبِرٍ بِالْحَقِّ مُعْطِيهِ ‏","","",""],[19465,19465,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏وَهَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَاشِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَكْحُولٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ حَوَالَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سَيَكُونُ جُنْدٌ ‏ ‏بِالشَّامِ ‏ ‏وَجُنْدٌ ‏ ‏بِالْيَمَنِ ‏ ‏فَقَالَ رَجُلٌ ‏ ‏فَخِرْ ‏ ‏لِي يَا رَسُولَ اللَّهِ إِذَا كَانَ ذَلِكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْكَ ‏ ‏بِالشَّامِ ‏ ‏عَلَيْكَ ‏ ‏بِالشَّامِ ‏ ‏ثَلَاثًا عَلَيْكَ ‏ ‏بِالشَّامِ ‏ ‏فَمَنْ أَبَى فَلْيَلْحَقْ بِيَمَنِهِ وَلْيَسْقِ مِنْ غُدُرِهِ ‏ ‏فَإِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى قَدْ تَكَفَّلَ لِي ‏ ‏بِالشَّامِ ‏ ‏وَأَهْلِهِ ‏ ‏قَالَ ‏ ‏أَبُو النَّضْرِ ‏ ‏مَرَّتَيْنِ فَلْيَلْحَقْ ‏ ‏بِيَمَنِهِ ‏","","",""],[19466,19466,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏الْأَحْنَفِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏عَمٍّ يُقَالُ لَهُ ‏ ‏جَارِيَةُ بْنُ قُدَامَةَ السَّعْدِيُّ ‏ ‏أَنَّهُ ‏ ‏سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏قُلْ لِي قَوْلًا يَنْفَعُنِي وَأَقْلِلْ عَلَيَّ لَعَلِّي ‏ ‏أَعِيهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَغْضَبْ فَأَعَادَ عَلَيْهِ مِرَارًا كُلُّ ذَلِكَ يَقُولُ لَا تَغْضَبْ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏الْأَحْنَفِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏عَمٍّ لَهُ يُقَالُ لَهُ ‏ ‏جَارِيَةُ بْنُ قُدَامَةَ ‏ ‏أَنَّ رَجُلًا قَالَ يَا رَسُولَ اللَّهِ قُلْ لِي قَوْلًا وَأَقْلِلْ عَلَيَّ وَذَكَرَ الْحَدِيثَ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏كَذَا ‏ ‏قَالَ ‏ ‏هِشَامٌ ‏ ‏قُلْتُ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏وَهُمْ يَقُولُونَ لَمْ يُدْرِكْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْنِي ‏ ‏يَحْيَى بْنَ سَعِيدٍ ‏ ‏يَقُولُ وَهُمْ يَقُولُونَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏الْأَحْنَفِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏جَارِيَةَ بْنِ قُدَامَةَ ‏ ‏قَالَ وَحَدَّثَنِي ‏ ‏عَمٌّ ‏ ‏لِي أَنَّهُ أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ عَلِّمْنِي شَيْئًا يَنْفَعُنِي وَأَقْلِلْ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[19467,19467,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي السَّلِيلِ ‏ ‏قَالَ ‏ ‏وَقَفَ عَلَيْنَا ‏ ‏رَجُلٌ ‏ ‏فِي مَجْلِسِنَا ‏ ‏بِالْبَقِيعِ ‏ ‏فَقَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَوْ ‏ ‏عَمِّي ‏ ‏أَنَّهُ ‏ ‏رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْبَقِيعِ ‏ ‏وَهُوَ يَقُولُ مَنْ يَتَصَدَّقُ ‏ ‏بِصَدَقَةٍ ‏ ‏أَشْهَدُ لَهُ بِهَا يَوْمَ الْقِيَامَةِ قَالَ فَحَلَلْتُ مِنْ عِمَامَتِي ‏ ‏لَوْثًا ‏ ‏أَوْ ‏ ‏لَوْثَيْنِ ‏ ‏وَأَنَا أُرِيدُ أَنْ أَتَصَدَّقَ بِهِمَا فَأَدْرَكَنِي مَا يُدْرِكُ بَنِي ‏ ‏آدَمَ ‏ ‏فَعَقَدْتُ عَلَيَّ عِمَامَتِي فَجَاءَ رَجُلٌ وَلَمْ أَرَ ‏ ‏بِالْبَقِيعِ ‏ ‏رَجُلًا أَشَدَّ سَوَادًا أَصْفَرَ مِنْهُ وَلَا ‏ ‏آدَمَ ‏ ‏يَعْبُرُ بِنَاقَةٍ لَمْ أَرَ ‏ ‏بِالْبَقِيعِ ‏ ‏نَاقَةً أَحْسَنَ مِنْهَا فَقَالَ يَا رَسُولَ اللَّهِ أَصَدَقَةٌ قَالَ نَعَمْ قَالَ دُونَكَ هَذِهِ النَّاقَةَ قَالَ فَلَزِمَهُ رَجُلٌ فَقَالَ هَذَا يَتَصَدَّقُ بِهَذِهِ فَوَاللَّهِ لَهِيَ خَيْرٌ مِنْهُ قَالَ فَسَمِعَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏كَذَبْتَ بَلْ هُوَ خَيْرٌ مِنْكَ وَمِنْهَا ثَلَاثَ مِرَارٍ ثُمَّ قَالَ وَيْلٌ لِأَصْحَابِ ‏ ‏الْمِئِينَ ‏ ‏مِنْ الْإِبِلِ ثَلَاثًا قَالُوا إِلَّا مَنْ يَا رَسُولَ اللَّهِ قَالَ إِلَّا مَنْ قَالَ بِالْمَالِ هَكَذَا وَهَكَذَا وَجَمَعَ بَيْنَ كَفَّيْهِ عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ ثُمَّ قَالَ قَدْ أَفْلَحَ ‏ ‏الْمُزْهِدُ ‏ ‏الْمُجْهِدُ ‏ ‏ثَلَاثًا ‏ ‏الْمُزْهِدُ ‏ ‏فِي الْعَيْشِ ‏ ‏الْمُجْهِدُ ‏ ‏فِي الْعِبَادَةِ ‏","","",""],[19468,19468,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏مُعَاوِيَةُ بْنُ قُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا فَسَدَ أَهْلُ ‏ ‏الشَّامِ ‏ ‏فَلَا خَيْرَ فِيكُمْ وَلَنْ تَزَالَ طَائِفَةٌ مِنْ أُمَّتِي مَنْصُورِينَ لَا يَضُرُّهُمْ مَنْ خَذَلَهُمْ حَتَّى تَقُومَ السَّاعَةُ ‏","","",""],[19469,19469,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏مَسَحَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى رَأْسِي ‏","","",""],[19470,19470,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏زِيَادُ بْنُ مِخْرَاقٍ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ قُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَجُلًا قَالَ يَا رَسُولَ اللَّهِ إِنِّي لَأَذْبَحُ الشَّاةَ وَإِنِّي أَرْحَمُهَا ‏ ‏أَوْ قَالَ إِنِّي لَأَرْحَمُ الشَّاةَ أَنْ أَذْبَحَهَا ‏ ‏فَقَالَ ‏ ‏وَالشَّاةُ إِنْ رَحِمْتَهَا رَحِمَكَ اللَّهُ ‏","","",""],[19471,19471,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صِيَامُ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ صِيَامُ الدَّهْرِ وَإِفْطَارُهُ ‏","","",""],[19472,19472,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏إِنَّ رَجُلًا كَانَ يَأْتِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَعَهُ ابْنٌ لَهُ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتُحِبُّهُ فَقَالَ يَا رَسُولَ اللَّهِ أَحَبَّكَ اللَّهُ كَمَا أُحِبُّهُ فَفَقَدَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا فَعَلَ ابْنُ فُلَانٍ قَالُوا يَا رَسُولَ اللَّهِ مَاتَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَبِيهِ ‏ ‏أَمَا تُحِبُّ أَنْ لَا تَأْتِيَ بَابًا مِنْ أَبْوَابِ الْجَنَّةِ إِلَّا وَجَدْتَهُ يَنْتَظِرُكَ فَقَالَ الرَّجُلُ يَا رَسُولَ اللَّهِ أَلَهُ خَاصَّةً أَوْ لِكُلِّنَا قَالَ بَلْ لِكُلِّكُمْ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُعَاوِيَةَ بْنَ قُرَّةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَجُلًا كَانَ يَأْتِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[19473,19473,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا فَسَدَ أَهْلُ ‏ ‏الشَّامِ ‏ ‏فَلَا خَيْرَ فِيكُمْ وَلَا يَزَالُ نَاسٌ مِنْ أُمَّتِي مَنْصُورِينَ لَا يُبَالُونَ مَنْ خَذَلَهُمْ حَتَّى تَقُومَ السَّاعَةُ ‏","","",""],[19474,19474,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ يَعْنِي الْأَشْيَبَ ‏ ‏وَأَبُو النَّضْرِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ عَبْدِ اللَّهِ بْنِ قُشَيْرٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَبُو النَّضْرِ ‏ ‏فِي حَدِيثِهِ ‏ ‏حَدَّثَنِي ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏عُرْوَةُ بْنُ عَبْدِ اللَّهِ بْنِ قُشَيْرٍ أَبُو مَهَلٍ الْجُعْفِيُّ ‏ ‏حَدَّثَنِي ‏ ‏مُعَاوِيَةُ بْنُ قُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏رَهْطٍ ‏ ‏مِنْ ‏ ‏مُزَيْنَةَ ‏ ‏فَبَايَعْنَاهُ ‏ ‏وَإِنَّ قَمِيصَهُ لَمُطْلَقٌ قَالَ ‏ ‏فَبَايَعْنَاهُ ‏ ‏ثُمَّ أَدْخَلْتُ يَدِي فِي جَيْبِ قَمِيصِهِ فَمَسِسْتُ ‏ ‏الْخَاتَمَ ‏ ‏قَالَ ‏ ‏عُرْوَةُ ‏ ‏فَمَا رَأَيْتُ ‏ ‏مُعَاوِيَةَ ‏ ‏وَلَا ابْنَهُ ‏ ‏قَالَ وَأُرَاهُ ‏ ‏يَعْنِي ‏ ‏إِيَاسًا ‏ ‏فِي شِتَاءٍ قَطُّ وَلَا حَرٍّ إِلَّا مُطْلِقَيْ إِزَارِهِمَا لَا يَزُرَّانِ ‏","","",""],[19475,19475,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏قُرَّةُ بْنُ خَالِدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُعَاوِيَةَ بْنَ قُرَّةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْتَأْذَنْتُهُ أَنْ أُدْخِلَ يَدِي فِي ‏ ‏جُرُبَّانِهِ ‏ ‏لِيَدْعُوَ لِي فَمَا مَنَعَهُ وَأَنَا أَلْمِسُهُ أَنْ ‏ ‏دَعَا لِي قَالَ فَوَجَدْتُ عَلَى ‏ ‏نُغْضِ ‏ ‏كَتِفِهِ مِثْلَ ‏ ‏السِّلْعَةِ ‏","","",""],[19476,19476,"","","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِيَاسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَعَا لَهُ وَمَسَحَ رَأْسَهُ ‏","","",""],[19477,19477,"","","‏ ‏حَدَّثَنَا ‏ ‏وَهْبٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فِي صِيَامِ ثَلَاثَةِ أَيَّامٍ مِنْ الشَّهْرِ صَوْمُ الدَّهْرِ وَإِفْطَارُهُ ‏","","",""],[19478,19478,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ حَمَّادُ بْنُ أُسَامَةَ ‏ ‏أَخْبَرَنَا ‏ ‏كَهْمَسٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏حَدَّثَنِي ‏ ‏هَرَمِيُّ بْنُ الْحَارِثِ ‏ ‏وَأُسَامَةُ بْنُ خُرَيْمٍ ‏ ‏وَكَانَا يُغَازِيَانِ فَحَدَّثَانِي حَدِيثًا وَلَمْ يَشْعُرْ كُلُّ وَاحِدٍ مِنْهُمَا أَنَّ صَاحِبَهُ حَدَّثَنِيهِ ‏ ‏عَنْ ‏ ‏مُرَّةَ الْبَهْزِيِّ ‏ ‏قَالَ ‏ ‏بَيْنَمَا نَحْنُ مَعَ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي طَرِيقٍ مِنْ طُرُقِ ‏ ‏الْمَدِينَةِ ‏ ‏فَقَالَ ‏ ‏كَيْفَ تَصْنَعُونَ فِي ‏ ‏فِتْنَةٍ ‏ ‏تَثُورُ فِي ‏ ‏أَقْطَارِ ‏ ‏الْأَرْضِ كَأَنَّهَا ‏ ‏صَيَاصِي ‏ ‏بَقَرٍ قَالُوا نَصْنَعُ مَاذَا يَا نَبِيَّ اللَّهِ قَالَ عَلَيْكُمْ هَذَا وَأَصْحَابَهُ ‏ ‏أَوْ اتَّبِعُوا هَذَا وَأَصْحَابَهُ ‏ ‏قَالَ فَأَسْرَعْتُ حَتَّى عَيِيتُ فَلَحِقْتُ الرَّجُلَ فَقُلْتُ هَذَا يَا رَسُولَ اللَّهِ قَالَ هَذَا فَإِذَا هُوَ ‏ ‏عُثْمَانُ بْنُ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ هَذَا وَأَصْحَابُهُ وَذَكَرَهُ ‏","","",""],[19479,19479,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ شَيْبَانَ ‏ ‏حَدَّثَنَا ‏ ‏بَحْرُ بْنُ مَرَّارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو بَكْرَةَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا أَنَا ‏ ‏أُمَاشِي رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ آخِذِي بِيَدِي وَرَجُلٌ عَنْ يَسَارِهِ فَإِذَا نَحْنُ بِقَبْرَيْنِ أَمَامَنَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُمَا لَيُعَذَّبَانِ وَمَا يُعَذَّبَانِ فِي كَبِيرٍ وَبَلَى فَأَيُّكُمْ يَأْتِينِي بِجَرِيدَةٍ فَاسْتَبَقْنَا فَسَبَقْتُهُ فَأَتَيْتُهُ بِجَرِيدَةٍ فَكَسَرَهَا نِصْفَيْنِ فَأَلْقَى عَلَى ذَا الْقَبْرِ قِطْعَةً وَعَلَى ذَا الْقَبْرِ قِطْعَةً ‏ ‏وَقَالَ إِنَّهُ يُهَوَّنُ عَلَيْهِمَا مَا كَانَتَا رَطْبَتَيْنِ وَمَا يُعَذَّبَانِ إِلَّا فِي الْبَوْلِ وَالْغِيبَةِ ‏","","",""],[19480,19480,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُيَيْنَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏وَوَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُيَيْنَةُ ‏ ‏وَيَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏عُيَيْنَةُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ ذَنْبٍ ‏ ‏أَحْرَى ‏ ‏أَنْ يُعَجِّلَ بِصَاحِبِهِ الْعُقُوبَةَ مَعَ مَا يُؤَخَّرُ لَهُ فِي الْآخِرَةِ مِنْ ‏ ‏بَغْيٍ ‏ ‏أَوْ قَطِيعَةِ رَحِمٍ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏أَنْ يُعَجِّلَ اللَّهُ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏يُعَجِّلُ اللَّهُ ‏ ‏وَقَالَ مَعَ مَا يُدَّخَرُ لَهُ ‏","","",""],[19481,19481,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُيَيْنَةَ ‏ ‏وَوَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عُيَيْنَةُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏لَقَدْ رَأَيْتُنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنَّا ‏ ‏لَنَكَادُ أَنْ ‏ ‏نَرْمُلَ ‏ ‏بِهَا ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏أَنْ ‏ ‏نَرْمُلَ ‏ ‏بِالْجِنَازَةِ ‏ ‏رَمَلًا ‏","","",""],[19482,19482,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عُيَيْنَةُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْتَمِسُوهَا فِي الْعَشْرِ الْأَوَاخِرِ لِتِسْعٍ يَبْقَيْنَ أَوْ لِسَبْعٍ يَبْقَيْنَ أَوْ لِخَمْسٍ أَوْ لِثَلَاثٍ أَوْ آخِرِ لَيْلَةٍ ‏","","",""],[19483,19483,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَأَبُو عَبْدِ الرَّحْمَنِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عُيَيْنَةُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَتَلَ مُعَاهَدًا فِي غَيْرِ ‏ ‏كُنْهِهِ ‏ ‏حَرَّمَ اللَّهُ عَلَيْهِ الْجَنَّةَ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏كُنْهُهُ ‏ ‏حَقٌّ ‏","","",""],[19484,19484,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا أَبُو عِمْرَانَ ‏ ‏شَيْخٌ بَصْرِيٌّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏شَيْخًا ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجَمَ ‏ ‏امْرَأَةً فَحَفَرَ لَهَا إِلَى ‏ ‏الثَّنْدُوَةِ ‏","","",""],[19485,19485,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏كَتَبَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَقْضِي الْحَاكِمُ بَيْنَ اثْنَيْنِ وَهُوَ غَضْبَانُ ‏","","",""],[19486,19486,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الْعَزِيزِ الرَّاسِبِيُّ ‏ ‏عَنْ ‏ ‏مَوْلًى لِأَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَنْبَانِ مُعَجَّلَانِ لَا يُؤَخَّرَانِ ‏ ‏الْبَغْيُ ‏ ‏وَقَطِيعَةُ الرَّحِمِ ‏","","",""],[19487,19487,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏عُثْمَانُ الشَّحَّامُ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الْكُفْرِ وَالْفَقْرِ وَعَذَابِ الْقَبْرِ ‏","","",""],[19488,19488,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ أَبُو سَلَمَةَ الشَّحَّامُ ‏ ‏حَدَّثَنِي ‏ ‏مُسْلِمُ بْنُ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَيَخْرُجُ قَوْمٌ أَحْدَاثٌ ‏ ‏أَحِدَّاءُ ‏ ‏أَشِدَّاءُ ‏ ‏ذَلِقَةٌ ‏ ‏أَلْسِنَتُهُمْ بِالْقُرْآنِ يَقْرَءُونَهُ لَا ‏ ‏يُجَاوِزُ ‏ ‏تَرَاقِيَهُمْ ‏ ‏فَإِذَا لَقِيتُمُوهُمْ ‏ ‏فَأَنِيمُوهُمْ ‏ ‏ثُمَّ إِذَا لَقِيتُمُوهُمْ فَاقْتُلُوهُمْ فَإِنَّهُ يُؤْجَرُ قَاتِلُهُمْ ‏","","",""],[19489,19489,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ عُبَيْدٍ ‏ ‏عَنِ ‏ ‏الْحَكَمِ بْنِ الْأَعْرَجِ ‏ ‏عَنِ ‏ ‏الْأَشْعَثِ بْنِ ثُرْمُلَةَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَتَلَ نَفْسًا مُعَاهَدَةً بِغَيْرِ حِلِّهَا حَرَّمَ اللَّهُ عَلَيْهِ الْجَنَّةَ أَنْ يَجِدَ رِيحَهَا ‏","","",""],[19490,19490,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرَأَيْتُمْ إِنْ كَانَ ‏ ‏جُهَيْنَةُ ‏ ‏وَأَسْلَمُ ‏ ‏وَغِفَارُ ‏ ‏وَمُزَيْنَةُ ‏ ‏خَيْرًا عِنْدَ اللَّهِ مِنْ ‏ ‏بَنِي أَسَدٍ ‏ ‏وَمِنْ ‏ ‏بَنِي تَمِيمٍ ‏ ‏وَمِنْ ‏ ‏بَنِي عَبْدِ اللَّهِ بْنِ غَطَفَانَ ‏ ‏وَمِنْ ‏ ‏بَنِي عَامِرِ بْنِ صَعْصَعَةَ ‏ ‏فَقَالَ رَجُلٌ قَدْ خَابُوا وَخَسِرُوا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُمْ خَيْرٌ مِنْ ‏ ‏بَنِي تَمِيمٍ ‏ ‏وَمِنْ ‏ ‏بَنِي عَامِرِ بْنِ صَعْصَعَةَ ‏ ‏وَمِنْ ‏ ‏بَنِي أَسَدٍ ‏ ‏وَمِنْ ‏ ‏بَنِي عَبْدِ اللَّهِ بْنِ غَطَفَانَ ‏","","",""],[19491,19491,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏وَقَالَ ‏ ‏إِسْمَاعِيلُ ‏ ‏مَرَّةً كُنَّا جُلُوسًا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَلَا أُنَبِّئُكُمْ بِأَكْبَرِ الْكَبَائِرِ ثَلَاثًا الْإِشْرَاكُ بِاللَّهِ عَزَّ وَجَلَّ ‏ ‏قَالَ ‏ ‏وَذُكِرَ الْكَبَائِرُ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ الْإِشْرَاكُ بِاللَّهِ عَزَّ وَجَلَّ وَعُقُوقُ الْوَالِدَيْنِ وَكَانَ مُتَّكِئًا ‏ ‏فَجَلَسَ وَقَالَ وَشَهَادَةُ الزُّورِ وَشَهَادَةُ الزُّورِ وَشَهَادَةُ الزُّورِ ‏ ‏أَوْ قَوْلُ الزُّورِ ‏ ‏وَشَهَادَةُ الزُّورِ فَمَا زَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكَرِّرُهَا حَتَّى قُلْنَا لَيْتَهُ سَكَتَ ‏","","",""],[19492,19492,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَبَ فِي حَجَّتِهِ فَقَالَ أَلَا إِنَّ الزَّمَانَ قَدْ اسْتَدَارَ كَهَيْئَتِهِ يَوْمَ خَلَقَ اللَّهُ السَّمَوَاتِ وَالْأَرْضَ السَّنَةُ اثْنَا عَشَرَ شَهْرًا مِنْهَا أَرْبَعَةٌ حُرُمٌ ثَلَاثٌ مُتَوَالِيَاتٌ ذُو الْقَعْدَةِ وَذُو الْحِجَّةِ وَالْمُحَرَّمُ وَرَجَبُ ‏ ‏مُضَرَ ‏ ‏الَّذِي بَيْنَ جُمَادَى وَشَعْبَانَ ثُمَّ قَالَ أَلَا أَيُّ يَوْمٍ هَذَا قُلْنَا اللَّهُ وَرَسُولُهُ أَعْلَمُ فَسَكَتَ حَتَّى ظَنَنَّا أَنَّهُ سَيُسَمِّيهِ بِغَيْرِ اسْمِهِ قَالَ أَلَيْسَ يَوْمَ النَّحْرِ قُلْنَا بَلَى ثُمَّ قَالَ أَيُّ شَهْرٍ هَذَا قُلْنَا اللَّهُ وَرَسُولُهُ أَعْلَمُ فَسَكَتَ حَتَّى ظَنَنَّا أَنَّهُ سَيُسَمِّيهِ بِغَيْرِ اسْمِهِ فَقَالَ أَلَيْسَ ذَا الْحِجَّةِ قُلْنَا بَلَى ثُمَّ قَالَ أَيُّ بَلَدٍ هَذَا قُلْنَا اللَّهُ وَرَسُولُهُ أَعْلَمُ فَسَكَتَ حَتَّى ظَنَنَّا أَنَّهُ سَيُسَمِّيهِ بِغَيْرِ اسْمِهِ قَالَ أَلَيْسَتْ الْبَلْدَةَ قُلْنَا بَلَى قَالَ ‏ ‏فَإِنَّ دِمَاءَكُمْ وَأَمْوَالَكُمْ ‏ ‏قَالَ وَأَحْسَبُهُ قَالَ وَأَعْرَاضَكُمْ ‏ ‏عَلَيْكُمْ حَرَامٌ كَحُرْمَةِ يَوْمِكُمْ هَذَا فِي شَهْرِكُمْ هَذَا فِي بَلَدِكُمْ هَذَا وَسَتَلْقَوْنَ رَبَّكُمْ فَيَسْأَلُكُمْ عَنْ أَعْمَالِكُمْ أَلَا لَا تَرْجِعُوا بَعْدِي ضُلَّالًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ أَلَا هَلْ بَلَّغْتُ أَلَا لِيُبَلِّغْ الشَّاهِدُ الْغَائِبَ مِنْكُمْ فَلَعَلَّ مَنْ يُبَلَّغُهُ يَكُونُ أَوْعَى لَهُ مِنْ بَعْضِ مَنْ يَسْمَعُهُ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏وَقَدْ كَانَ ذَاكَ قَالَ قَدْ كَانَ بَعْضُ مَنْ بُلِّغَهُ أَوْعَى لَهُ مِنْ بَعْضِ مَنْ سَمِعَهُ ‏","","",""],[19493,19493,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنِ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ يَعْنِي ابْنَ سِيرِينَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ ذَلِكَ الْيَوْمُ قَعَدَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى بَعِيرٍ وَأَخَذَ رَجُلٌ بِزِمَامِهِ ‏ ‏أَوْ بِخِطَامِهِ ‏ ‏فَقَالَ أَيُّ يَوْمٍ يَوْمُكُمْ هَذَا قَالَ فَسَكَتْنَا حَتَّى ظَنَنَّا أَنَّهُ سَيُسَمِّيهِ سِوَى اسْمِهِ قَالَ أَلَيْسَ بِالنَّحْرِ قَالَ قُلْنَا بَلَى قَالَ فَأَيُّ شَهْرٍ شَهْرُكُمْ هَذَا قَالَ فَسَكَتْنَا حَتَّى ظَنَنَّا أَنَّهُ سَيُسَمِّيهِ سِوَى اسْمِهِ فَقَالَ أَلَيْسَ بِذِي الْحِجَّةِ قَالَ قُلْنَا بَلَى قَالَ فَأَيُّ بَلَدٍ بَلَدُكُمْ هَذَا قَالَ فَسَكَتْنَا حَتَّى ظَنَنَّا أَنَّهُ سَيُسَمِّيهِ سِوَى اسْمِهِ فَقَالَ أَلَيْسَ بِالْبَلْدَةِ قَالَ قُلْنَا بَلَى قَالَ ‏ ‏فَإِنَّ دِمَاءَكُمْ وَأَمْوَالَكُمْ وَأَعْرَاضَكُمْ بَيْنَكُمْ حَرَامٌ كَحُرْمَةِ يَوْمِكُمْ هَذَا فِي شَهْرِكُمْ هَذَا فِي بَلَدِكُمْ هَذَا أَلَا فَلْيُبَلِّغْ الشَّاهِدُ الْغَائِبَ فَإِنَّ الشَّاهِدَ عَسَى أَنْ يُبَلِّغَهُ مَنْ هُوَ أَوْعَى لَهُ مِنْهُ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏فَقَالَ رَجُلٌ فَقَدْ كَانَ ذَاكَ ‏","","",""],[19494,19494,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏عُيَيْنَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏لَقَدْ رَأَيْتُنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنَّا ‏ ‏لَنَرْمُلُ ‏ ‏بِالْجِنَازَةِ ‏ ‏رَمَلًا ‏","","",""],[19495,19495,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقْضِي الْقَاضِي بَيْنَ اثْنَيْنِ وَهُوَ غَضْبَانُ ‏","","",""],[19496,19496,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏وَرِبْعِىُّ بْنُ إِبْرَاهِيمَ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏كَسَفَتْ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَامَ يَجُرُّ ثَوْبَهُ مُسْتَعْجِلًا حَتَّى أَتَى الْمَسْجِدَ ‏ ‏وَثَابَ ‏ ‏النَّاسُ فَصَلَّى رَكْعَتَيْنِ فَجُلِّيَ عَنْهَا ثُمَّ أَقْبَلَ عَلَيْنَا فَقَالَ ‏ ‏إِنَّ الشَّمْسَ وَالْقَمَرَ آيَتَانِ مِنْ آيَاتِ اللَّهِ تَبَارَكَ وَتَعَالَى يُخَوِّفُ بِهِمَا عِبَادَهُ وَلَا يَنْكَسِفَانِ لِمَوْتِ أَحَدٍ ‏ ‏قَالَ وَكَانَ ابْنُهُ ‏ ‏إِبْرَاهِيمُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏مَاتَ ‏ ‏فَإِذَا رَأَيْتُمْ مِنْهُمَا شَيْئًا فَصَلُّوا وَادْعُوا حَتَّى يُكْشَفَ مِنْهُمَا مَا بِكُمْ ‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَنَّهُ حَدَّثَهُ ‏ ‏قَالَ انْكَسَفَتْ الشَّمْسُ عَلَى عَهْدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ عِنْدَهُ ‏ ‏فَوَثَبَ ‏ ‏فَزِعًا يَجُرُّ ثَوْبَهُ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[19497,19497,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى وَيُقَالُ لَهُ إِسْرَائِيلُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا بَكْرَةَ ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ ‏ ‏وَحَسَنٌ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏مَعَهُ وَهُوَ يُقْبِلُ عَلَى النَّاسِ مَرَّةً وَعَلَيْهِ مَرَّةً وَيَقُولُ ‏ ‏إِنَّ ابْنِي هَذَا سَيِّدٌ وَلَعَلَّ اللَّهَ تَبَارَكَ وَتَعَالَى أَنْ يُصْلِحَ بِهِ بَيْنَ فِئَتَيْنِ مِنْ الْمُسْلِمِينَ ‏","","",""],[19498,19498,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَنْبَغِي لِلْقَاضِي ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً لِلْحَاكِمِ ‏ ‏أَنْ يَحْكُمَ بَيْنَ اثْنَيْنِ وَهُوَ غَضْبَانُ ‏","","",""],[19499,19499,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏ذُكِرَ الْكَبَائِرُ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ الْإِشْرَاكُ بِاللَّهِ تَبَارَكَ وَتَعَالَى وَعُقُوقُ الْوَالِدَيْنِ وَكَانَ مُتَّكِئًا فَجَلَسَ فَقَالَ وَشَهَادَةُ الزُّورِ وَشَهَادَةُ الزُّورِ ‏ ‏أَوْ قَوْلُ الزُّورِ ‏ ‏فَمَا زَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكَرِّرُهَا حَتَّى قُلْنَا لَيْتَهُ سَكَتَ ‏ ‏و قَالَ ‏ ‏مَرَّةً ‏ ‏أَخْبَرَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ كُنَّا جُلُوسًا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَلَا أُنَبِّئُكُمْ بِأَكْبَرِ الْكَبَائِرِ الْإِشْرَاكُ بِاللَّهِ تَعَالَى ‏ ‏فَذَكَرَهُ ‏","","",""],[19500,19500,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرَةَ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو بَكْرَةَ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏نَبْتَاعَ ‏ ‏الْفِضَّةَ بِالْفِضَّةِ وَالذَّهَبَ بِالذَّهَبِ إِلَّا سَوَاءً بِسَوَاءٍ وَأَمَرَنَا أَنْ ‏ ‏نَبْتَاعَ ‏ ‏الْفِضَّةَ فِي الذَّهَبِ وَالذَّهَبَ فِي الْفِضَّةِ كَيْفَ شِئْنَا ‏ ‏فَقَالَ ‏ ‏لَهُ ‏ ‏ثَابِتُ بْنُ عُبَيْدٍ ‏ ‏يَدًا بِيَدٍ قَالَ هَكَذَا سَمِعْتُ ‏","","",""],[19501,19501,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعْدًا ‏ ‏يَقُولُ ‏ ‏سَمِعَتْ أُذُنَايَ وَوَعَى قَلْبِي أَنَّ ‏ ‏مَنْ ‏ ‏ادَّعَى ‏ ‏إِلَى غَيْرِ أَبِيهِ وَهُوَ يَعْلَمُ أَنَّهُ غَيْرُ أَبِيهِ فَالْجَنَّةُ عَلَيْهِ حَرَامٌ ‏ ‏قَالَ ‏ ‏فَلَقِيتُ ‏ ‏أَبَا بَكْرَةَ ‏ ‏فَحَدَّثْتُهُ فَقَالَ ‏ ‏وَأَنَا سَمِعَتْ أُذُنَايَ وَوَعَى قَلْبِي مِنْ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[19502,19502,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ عُبَيْدٍ ‏ ‏عَنِ ‏ ‏الْحَكَمِ بْنِ الْأَعْرَجِ ‏ ‏عَنِ ‏ ‏الْأَشْعَثِ بْنِ ثُرْمُلَةَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَتَلَ نَفْسًا ‏ ‏مُعَاهَدَةً ‏ ‏بِغَيْرِ حِلِّهَا حَرَّمَ اللَّهُ تَبَارَكَ وَتَعَالَى عَلَيْهِ الْجَنَّةَ لَمْ يَشُمَّ رِيحَهَا ‏","","",""],[19503,19503,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏عُيَيْنَةُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ ذَنْبٍ ‏ ‏أَحْرَى ‏ ‏أَنْ يُعَجِّلَ اللَّهُ تَبَارَكَ وَتَعَالَى الْعُقُوبَةَ لِصَاحِبِهِ فِي الدُّنْيَا مَعَ مَا يَدَّخِرُ لَهُ فِي الْآخِرَةِ مِنْ ‏ ‏الْبَغْيِ ‏ ‏وَقَطِيعَةِ الرَّحِمِ ‏","","",""],[19504,19504,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَحْسَبُهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏شَهْرَانِ لَا يَنْقُصَانِ شَهْرَا عِيدِ رَمَضَانَ وَذِي الْحِجَّةِ ‏","","",""],[19505,19505,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُيَيْنَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏خَرَجْتُ فِي جَنَازَةِ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ ‏ ‏قَالَ فَجَعَلَ رِجَالٌ مِنْ أَهْلِهِ يَسْتَقْبِلُونَ الْجِنَازَةَ فَيَمْشُونَ عَلَى أَعْقَابِهِمْ وَيَقُولُونَ رُوَيْدًا بَارَكَ اللَّهُ فِيكُمْ قَالَ فَلَحِقَنَا ‏ ‏أَبُو بَكْرَةَ ‏ ‏مِنْ طَرِيقِ ‏ ‏المِرْبَدِ ‏ ‏فَلَمَّا رَأَى أُولَئِكَ وَمَا يَصْنَعُونَ حَمَلَ عَلَيْهِمْ بِبَغْلَتِهِ وَأَهْوَى لَهُمْ بِالسَّوْطِ وَقَالَ خَلُّوا فَوَالَّذِي كَرَّمَ وَجْهَ ‏ ‏أَبِي الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ رَأَيْتُنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنَّا ‏ ‏لَنَكَادُ أَنْ ‏ ‏نَرْمُلَ ‏ ‏بِهَا ‏ ‏وَقَالَ ‏ ‏يَحْيَى ‏ ‏مَرَّةً لَقَدْ رَأَيْتُنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[19506,19506,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُيَيْنَةَ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الدَّجَّالُ ‏ ‏أَعْوَرُ بِعَيْنِ الشِّمَالِ بَيْنَ عَيْنَيْهِ مَكْتُوبٌ كَافِرٌ يَقْرَؤُهُ الْأُمِّيُّ وَالْكَاتِبُ ‏","","",""],[19507,19507,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُيَيْنَةَ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَنْ يُفْلِحَ قَوْمٌ أَسْنَدُوا أَمْرَهُمْ إِلَى امْرَأَةٍ ‏","","",""],[19508,19508,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُيَيْنَةَ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَتَلَ ‏ ‏مُعَاهَدًا ‏ ‏فِي غَيْرِ ‏ ‏كُنْهِهِ ‏ ‏حَرَّمَ اللَّهُ عَلَيْهِ ‏ ‏الْجَنَّةَ أَنْ يَجِدَ رِيحَهَا ‏","","",""],[19509,19509,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُيَيْنَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏ذَكَرْتُ لَيْلَةَ الْقَدْرِ عِنْدَ ‏ ‏أَبِي بَكْرَةَ ‏ ‏فَقَالَ ‏ ‏مَا أَنَا بِطَالِبِهَا إِلَّا فِي الْعَشْرِ الْأَوَاخِرِ بَعْدَ شَيْءٍ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعْتُهُ يَقُولُ ‏ ‏الْتَمِسُوهَا ‏ ‏فِي الْعَشْرِ الْأَوَاخِرِ مِنْ تِسْعٍ يَبْقَيْنَ أَوْ سَبْعٍ يَبْقَيْنَ أَوْ خَمْسٍ يَبْقَيْنَ أَوْ ثَلَاثٍ يَبْقَيْنَ أَوْ آخِرِ لَيْلَةٍ ‏","","",""],[19510,19510,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏أَشْعَثُ ‏ ‏عَنْ ‏ ‏زِيَادٍ الْأَعْلَمِ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَنَّهُ ‏ ‏رَكَعَ دُونَ الصَّفِّ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَادَكَ اللَّهُ حِرْصًا وَلَا تَعُدْ ‏","","",""],[19511,19511,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُهَلَّبِ بْنِ أَبِي حَبِيبَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَقُولَنَّ أَحَدُكُمْ إِنِّي قُمْتُ رَمَضَانَ ‏ ‏كُلَّهُ وَصُمْتُهُ ‏ ‏قَالَ ‏ ‏فَلَا أَدْرِي أَكَرِهَ التَّزْكِيَةَ أَمْ لَا فَلَا بُدَّ مِنْ غَفْلَةٍ أَوْ رَقْدَةٍ ‏","","",""],[19512,19512,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏قُرَّةُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ سِيرِينَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏وَعَنْ ‏ ‏رَجُلٍ ‏ ‏آخَرَ ‏ ‏وَهُوَ فِي نَفْسِي أَفْضَلُ مِنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ غَيْرُ أَبِي عَنْ ‏ ‏يَحْيَى ‏ ‏فِي هَذَا الْحَدِيثِ أُفَضِّلُ فِي نَفْسِي ‏ ‏حُمَيْدَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَبَ النَّاسَ ‏ ‏بِمِنًى ‏ ‏فَقَالَ أَلَا تَدْرُونَ أَيُّ يَوْمٍ هَذَا قُلْنَا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ فَسَكَتَ حَتَّى ظَنَنَّا أَنَّهُ سَيُسَمِّيهِ بِغَيْرِ اسْمِهِ فَقَالَ أَلَيْسَ بِيَوْمِ ‏ ‏النَّحْرِ ‏ ‏قُلْنَا نَعَمْ قَالَ أَيُّ بَلَدٍ هَذَا قُلْنَا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ أَلَيْسَ بِالْبَلْدَةِ قُلْنَا بَلَى يَا رَسُولَ اللَّهِ قَالَ ‏ ‏فَإِنَّ دِمَاءَكُمْ وَأَمْوَالَكُمْ وَأَعْرَاضَكُمْ وَأَبْشَارَكُمْ حَرَامٌ كَحُرْمَةِ يَوْمِكُمْ هَذَا فِي شَهْرِكُمْ هَذَا فِي بَلَدِكُمْ هَذَا أَلَا هَلْ بَلَّغْتُ قُلْنَا نَعَمْ قَالَ اللَّهُمَّ اشْهَدْ لِيُبَلِّغْ الشَّاهِدُ الْغَائِبَ فَإِنَّهُ رُبَّ مُبَلِّغٍ يُبَلِّغُهُ مَنْ هُوَ أَوْعَى لَهُ مِنْهُ فَكَانَ كَذَلِكَ وَقَالَ لَا تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ‏ ‏فَلَمَّا كَانَ يَوْمُ حَرْقِ ‏ ‏ابْنِ الْحَضْرَمِيِّ ‏ ‏حَرَّقَهُ ‏ ‏جَارِيَةُ بْنُ قُدَامَةَ ‏ ‏قَالَ أَشْرَفُوا عَلَى ‏ ‏أَبِي بَكْرَةَ ‏ ‏فَقَالُوا هَذَا ‏ ‏أَبُو بَكْرَةَ ‏ ‏فَقَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏فَحَدَّثَتْنِي ‏ ‏أُمِّي ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرَةَ ‏ ‏قَالَ ‏ ‏لَوْ دَخَلُوا عَلَيَّ مَا ‏ ‏بَهَشْتُ ‏ ‏إِلَيْهِمْ بِقَصَبَةٍ ‏","","",""],[19513,19513,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَشْعَثَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى بِهَؤُلَاءِ الرَّكْعَتَيْنِ وَهَؤُلَاءِ الرَّكْعَتَيْنِ فَكَانَتْ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَعًا وَلَهُمْ رَكْعَتَيْنِ رَكْعَتَيْنِ ‏","","",""],[19514,19514,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ الشَّحَّامُ ‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ فِي ‏ ‏دُبُرِ ‏ ‏كُلِّ صَلَاةٍ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الْكُفْرِ وَالْفَقْرِ وَعَذَابِ الْقَبْرِ ‏","","",""],[19515,19515,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرَأَيْتُمْ إِنْ كَانَتْ ‏ ‏جُهَيْنَةُ ‏ ‏وَأَسْلَمُ ‏ ‏وَغِفَارُ ‏ ‏خَيْرًا مِنْ ‏ ‏بَنِي تَمِيمٍ ‏ ‏وَبَنِي عَبْدِ اللَّهِ بْنِ غَطَفَانَ ‏ ‏وَبَنِي عَامِرِ بْنِ صَعْصَعَةَ ‏ ‏وَمَدَّ بِهَا صَوْتَهُ قَالُوا يَا رَسُولَ اللَّهِ قَدْ خَابُوا وَخَسِرُوا قَالَ فَوَالَّذِي نَفْسِي بِيَدِهِ لَهُمْ خَيْرٌ ‏","","",""],[19516,19516,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ شَيْبَانَ ‏ ‏عَنْ ‏ ‏بَحْرِ بْنِ مَرَّارٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ أَمْشِي مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَرَّ عَلَى قَبْرَيْنِ فَقَالَ مَنْ يَأْتِينِي بِجَرِيدَةِ نَخْلٍ قَالَ فَاسْتَبَقْتُ أَنَا وَرَجُلٌ آخَرُ فَجِئْنَا ‏ ‏بِعَسِيبٍ ‏ ‏فَشَقَّهُ بِاثْنَيْنِ فَجَعَلَ عَلَى هَذَا وَاحِدَةً وَعَلَى هَذَا وَاحِدَةً ثُمَّ قَالَ أَمَا إِنَّهُ سَيُخَفَّفُ عَنْهُمَا مَا كَانَ فِيهِمَا مِنْ بُلُولَتِهِمَا شَيْءٌ ثُمَّ قَالَ ‏ ‏إِنَّهُمَا لَيُعَذَّبَانِ فِي الْغِيبَةِ وَالْبَوْلِ ‏","","",""],[19517,19517,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ الشَّحَّامُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُسْلِمُ بْنُ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهَا سَتَكُونُ ‏ ‏فِتْنَةٌ ‏ ‏الْمُضْطَجِعُ فِيهَا خَيْرٌ مِنْ الْجَالِسِ وَالْجَالِسُ خَيْرٌ مِنْ الْقَائِمِ وَالْقَائِمُ فِيهَا خَيْرٌ مِنْ الْمَاشِي وَالْمَاشِي خَيْرٌ مِنْ السَّاعِي قَالَ فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ فَمَا تَأْمُرُنِي قَالَ مَنْ كَانَتْ لَهُ إِبِلٌ فَلْيَلْحَقْ بِإِبِلِهِ وَمَنْ كَانَتْ لَهُ غَنَمٌ ‏ ‏فَلْيَلْحَقْ بِغَنَمِهِ وَمَنْ كَانَتْ لَهُ أَرْضٌ فَلْيَلْحَقْ بِأَرْضِهِ وَمَنْ لَمْ يَكُنْ لَهُ شَيْءٌ فَلْيَعْمِدْ إِلَى سَيْفِهِ فَلْيَضْرِبْ بِحَدِّهِ صَخْرَةً ثُمَّ لِيَنْجُ إِنْ اسْتَطَاعَ النَّجَاةَ ثُمَّ لِيَنْجُ إِنْ اسْتَطَاعَ النَّجَاةَ ‏","","",""],[19518,19518,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْعَوَّامُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ جُمْهَانَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏ذَكَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْضًا يُقَالُ لَهَا ‏ ‏الْبَصْرَةُ ‏ ‏إِلَى جَنْبِهَا نَهَرٌ يُقَالُ لَهُ دِجْلَةُ ذُو نَخْلٍ كَثِيرٍ وَيَنْزِلُ بِهِ ‏ ‏بَنُو قَنْطُورَاءَ ‏ ‏فَيَتَفَرَّقُ النَّاسُ ثَلَاثَ فِرَقٍ فِرْقَةٌ تَلْحَقُ بِأَصْلِهَا وَهَلَكُوا وَفِرْقَةٌ تَأْخُذُ عَلَى أَنْفُسِهَا وَكَفَرُوا وَفِرْقَةٌ يَجْعَلُونَ ‏ ‏ذَرَارِيَّهُمْ ‏ ‏خَلْفَ ظُهُورِهِمْ فَيُقَاتِلُونَ قَتْلَاهُمْ شُهَدَاءُ يَفْتَحُ اللَّهُ تَبَارَكَ وَتَعَالَى عَلَى بَقِيَّتِهِمْ ‏ ‏وَشَكَّ ‏ ‏يَزِيدُ ‏ ‏فِيهِ مَرَّةً فَقَالَ ‏ ‏الْبُصَيْرَةُ ‏ ‏أَوْ ‏ ‏الْبَصْرَةُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ ‏ ‏أَخْبَرَنَا ‏ ‏الْعَوَّامُ بْنُ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُمْهَانَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَتَنْزِلُنَّ أَرْضًا يُقَالُ لَهَا ‏ ‏الْبَصْرَةُ ‏ ‏أَوْ ‏ ‏الْبُصَيْرَةُ ‏ ‏عَلَى دِجْلَةَ نَهَرٌ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏ ‏قَالَ ‏ ‏الْعَوَّامُ ‏ ‏بَنُو قَنْطُورَاءَ ‏ ‏هُمْ ‏ ‏التُّرْكُ ‏","","",""],[19519,19519,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَجُلًا قَالَ يَا رَسُولَ اللَّهِ ‏ ‏أَيُّ النَّاسِ خَيْرٌ قَالَ مَنْ طَالَ عُمُرُهُ وَحَسُنَ عَمَلُهُ قَالَ فَأَيُّ النَّاسِ شَرٌّ قَالَ مَنْ طَالَ عُمُرُهُ وَسَاءَ عَمَلُهُ ‏","","",""],[19520,19520,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقُولَنَّ أَحَدُكُمْ صُمْتُ رَمَضَانَ كُلَّهُ وَلَا قُمْتُهُ كُلَّهُ ‏ ‏قَالَ ‏ ‏الْحَسَنُ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و قَالَ ‏ ‏يَزِيدُ ‏ ‏مَرَّةً ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏اللَّهُ أَعْلَمُ أَخَافَ عَلَى أُمَّتِهِ التَّزْكِيَةَ أَوْ لَا بُدَّ مِنْ رَاقِدٍ أَوْ غَافِلٍ ‏","","",""],[19521,19521,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏عُيَيْنَةُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏ذَكَرْتُ لَيْلَةَ الْقَدْرِ عِنْدَ ‏ ‏أَبِي بَكْرَةَ ‏ ‏فَقَالَ ‏ ‏مَا أَنَا بِمُلْتَمِسِهَا بَعْدَمَا ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا فِي عَشْرِ الْأَوَاخِرِ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْتَمِسُوهَا ‏ ‏فِي الْعَشْرِ الْأَوَاخِرِ فِي ‏ ‏الْوِتْرِ ‏ ‏مِنْهُ ‏ ‏قَالَ ‏ ‏فَكَانَ ‏ ‏أَبُو بَكْرَةَ ‏ ‏يُصَلِّي فِي الْعِشْرِينَ مِنْ رَمَضَانَ كَصَلَاتِهِ فِي ‏ ‏سَائِرِ ‏ ‏السَّنَةِ فَإِذَا دَخَلَ الْعَشْرُ اجْتَهَدَ ‏","","",""],[19522,19522,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْكُثُ أَبَوَا ‏ ‏الدَّجَّالِ ‏ ‏ثَلَاثِينَ عَامًا لَا يُولَدُ لَهُمَا ثُمَّ يُولَدُ لَهُمَا غُلَامٌ أَعْوَرُ أَضَرُّ شَيْءٍ وَأَقَلُّهُ نَفْعًا تَنَامُ عَيْنَاهُ وَلَا يَنَامُ قَلْبُهُ ثُمَّ ‏ ‏نَعَتَ ‏ ‏أَبَوَيْهِ فَقَالَ أَبُوهُ رَجُلٌ طُوَالٌ ‏ ‏مُضْطَرِبُ ‏ ‏اللَّحْمِ طَوِيلُ الْأَنْفِ كَأَنَّ أَنْفَهُ مِنْقَارٌ وَأُمُّهُ امْرَأَةٌ ‏ ‏فِرْضَاخِيَّةٌ ‏ ‏عَظِيمَةُ الثَّدْيَيْنِ قَالَ فَبَلَغَنَا أَنَّ مَوْلُودًا مِنْ ‏ ‏الْيَهُودِ ‏ ‏وُلِدَ ‏ ‏بِالْمَدِينَةِ ‏ ‏قَالَ فَانْطَلَقْتُ أَنَا ‏ ‏وَالزُّبَيْرُ بْنُ الْعَوَّامِ ‏ ‏حَتَّى دَخَلْنَا عَلَى أَبَوَيْهِ فَرَأَيْنَا فِيهِمَا ‏ ‏نَعْتَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِذَا هُوَ ‏ ‏مُنْجَدِلٌ ‏ ‏فِي الشَّمْسِ فِي ‏ ‏قَطِيفَةٍ ‏ ‏لَهُ ‏ ‏هَمْهَمَةٌ ‏ ‏فَسَأَلْنَا أَبَوَيْهِ فَقَالَا مَكَثْنَا ثَلَاثِينَ عَامًا لَا يُولَدُ لَنَا ثُمَّ وُلِدَ لَنَا غُلَامٌ أَعْوَرُ أَضَرُّ شَيْءٍ وَأَقَلُّهُ نَفْعًا فَلَمَّا خَرَجْنَا مَرَرْنَا بِهِ فَقَالَ مَا كُنْتُمَا فِيهِ قُلْنَا وَسَمِعْتَ قَالَ نَعَمْ إِنَّهُ تَنَامُ عَيْنَايَ وَلَا يَنَامُ قَلْبِي فَإِذَا هُوَ ‏ ‏ابْنُ صَيَّادٍ ‏","","",""],[19523,19523,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَشْعَثُ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏خَطَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏النَّحْرِ ‏ ‏عَلَى نَاقَةٍ لَهُ قَالَ فَجَعَلَ يَتَكَلَّمُ هَاهُنَا مَرَّةً وَهَاهُنَا مَرَّةً عِنْدَ كُلِّ قَوْمٍ ثُمَّ قَالَ أَيُّ يَوْمٍ هَذَا قَالَ فَسَكَتْنَا حَتَّى ظَنَنَّا أَنَّهُ سَيُسَمِّيهِ غَيْرَ اسْمِهِ قَالَ أَلَيْسَ يَوْمَ ‏ ‏النَّحْرِ ‏ ‏قَالَ قُلْنَا بَلَى ثُمَّ قَالَ أَيُّ شَهْرٍ هَذَا قَالَ فَسَكَتْنَا حَتَّى ظَنَنَّا أَنَّهُ سَيُسَمِّيهِ غَيْرَ اسْمِهِ قَالَ ثُمَّ قَالَ أَلَيْسَ ذَا الْحِجَّةِ قَالَ قُلْنَا بَلَى ثُمَّ قَالَ أَيُّ بَلَدٍ هَذَا قَالَ فَسَكَتْنَا حَتَّى ظَنَنَّا أَنَّهُ سَيُسَمِّيهِ غَيْرَ اسْمِهِ قَالَ ثُمَّ قَالَ أَلَيْسَ الْبَلْدَةَ الْحَرَامَ قَالَ قُلْنَا بَلَى قَالَ ‏ ‏فَإِنَّ دِمَاءَكُمْ وَأَمْوَالَكُمْ وَأَعْرَاضَكُمْ حَرَامٌ عَلَيْكُمْ إِلَى أَنْ تَلْقَوْا رَبَّكُمْ تَعَالَى كَحُرْمَةِ يَوْمِكُمْ ‏ ‏هَذَا فِي شَهْرِكُمْ هَذَا فِي بَلَدِكُمْ هَذَا ثُمَّ قَالَ لِيُبَلِّغْ الشَّاهِدُ مِنْكُمْ الْغَائِبَ فَلَعَلَّ الْغَائِبَ أَنْ يَكُونَ أَوْعَى لَهُ مِنْ الشَّاهِدِ ‏","","",""],[19524,19524,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏زِيَادٍ الْأَعْلَمِ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَفْتَحَ الصَّلَاةَ فَكَبَّرَ ثُمَّ أَوْمَأَ إِلَيْهِمْ أَنْ مَكَانَكُمْ ثُمَّ دَخَلَ فَخَرَجَ وَرَأْسُهُ يَقْطُرُ فَصَلَّى بِهِمْ فَلَمَّا قَضَى الصَّلَاةَ قَالَ ‏ ‏إِنَّمَا أَنَا بَشَرٌ وَإِنِّي كُنْتُ جُنُبًا ‏","","",""],[19525,19525,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا ‏ ‏فَرَطُكُمْ ‏ ‏عَلَى الْحَوْضِ ‏","","",""],[19526,19526,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُمْ ذَكَرُوا رَجُلًا عِنْدَهُ فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ مَا مِنْ رَجُلٍ بَعْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْضَلُ مِنْهُ فِي كَذَا وَكَذَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيْحَكَ قَطَعْتَ عُنُقَ صَاحِبِكَ مِرَارًا يَقُولُ ذَلِكَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ كَانَ أَحَدُكُمْ مَادِحًا أَخَاهُ لَا مَحَالَةَ فَلْيَقُلْ أَحْسَبُ فُلَانًا إِنْ كَانَ يَرَى أَنَّهُ كَذَاكَ وَلَا أُزَكِّي عَلَى اللَّهِ تَبَارَكَ وَتَعَالَى أَحَدًا وَحَسِيبُهُ اللَّهُ أَحْسَبُهُ كَذَا وَكَذَا ‏","","",""],[19527,19527,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي يَعْقُوبَ الضَّبِّيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ أَبِي بَكْرَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏الْأَقْرَعَ بْنَ حَابِسٍ ‏ ‏جَاءَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّمَا ‏ ‏بَايَعَكَ ‏ ‏سُرَّاقُ الْحَجِيجِ مِنْ ‏ ‏أَسْلَمَ ‏ ‏وَغِفَارَ ‏ ‏وَمُزَيْنَةَ ‏ ‏وَأَحْسَبُ ‏ ‏جُهَيْنَةَ ‏ ‏مُحَمَّدٌ ‏ ‏الَّذِي يَشُكُّ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرَأَيْتَ إِنْ كَانَ ‏ ‏أَسْلَمُ ‏ ‏وَغِفَارُ ‏ ‏وَمُزَيْنَةُ ‏ ‏وَأَحْسَبُ ‏ ‏جُهَيْنَةَ ‏ ‏خَيْرًا مِنْ ‏ ‏بَنِي تَمِيمٍ ‏ ‏وَبَنِي عَامِرٍ ‏ ‏وَأَسَدٍ ‏ ‏وَغَطَفَانَ ‏ ‏أَخَابُوا وَخَسِرُوا فَقَالَ نَعَمْ فَقَالَ وَالَّذِي نَفْسِي بِيَدِهِ إِنَّهُمْ لَأَخْيَرُ مِنْهُ إِنَّهُمْ لَأَخْيَرُ مِنْهُمْ ‏","","",""],[19528,19528,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏رِبْعِيِّ بْنِ حِرَاشٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا الْمُسْلِمَانِ حَمَلَ أَحَدُهُمَا عَلَى صَاحِبِهِ السِّلَاحَ فَهُمَا عَلَى طَرَفِ جَهَنَّمَ فَإِذَا قَتَلَ أَحَدُهُمَا صَاحِبَهُ دَخَلَاهَا جَمِيعًا ‏","","",""],[19529,19529,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَتَانِي ‏ ‏جِبْرِيلُ ‏ ‏وَمِيكَائِيلُ ‏ ‏عَلَيْهِمَا السَّلَام ‏ ‏فَقَالَ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏اقْرَأْ الْقُرْآنَ عَلَى حَرْفٍ وَاحِدٍ فَقَالَ ‏ ‏مِيكَائِيلُ ‏ ‏اسْتَزِدْهُ قَالَ اقْرَأْهُ عَلَى سَبْعَةِ أَحْرُفٍ كُلِّهَا شَافٍ كَافٍ مَا لَمْ تُخْتَمْ آيَةُ رَحْمَةٍ بِعَذَابٍ ‏ ‏أَوْ آيَةُ عَذَابٍ بِرَحْمَةٍ ‏","","",""],[19530,19530,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏زِيَادٍ الْأَعْلَمِ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ فِي صَلَاةِ الْفَجْرِ ‏ ‏فَأَوْمَأَ ‏ ‏إِلَيْهِمْ أَنْ مَكَانَكُمْ فَذَهَبَ ثُمَّ جَاءَ وَرَأْسُهُ يَقْطُرُ فَصَلَّى بِهِمْ ‏","","",""],[19531,19531,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَقُولَنَّ أَحَدُكُمْ إِنِّي قُمْتُ رَمَضَانَ كُلَّهُ ‏","","",""],[19532,19532,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ عَبْدِ اللَّهِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏أَكْثَرَ النَّاسُ فِي ‏ ‏مُسَيْلِمَةَ ‏ ‏قَبْلَ أَنْ يَقُولَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِ شَيْئًا فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطِيبًا فَقَالَ ‏ ‏أَمَّا بَعْدُ فَفِي شَأْنِ هَذَا الرَّجُلِ الَّذِي قَدْ أَكْثَرْتُمْ فِيهِ وَإِنَّهُ كَذَّابٌ مِنْ ثَلَاثِينَ كَذَّابًا يَخْرُجُونَ بَيْنَ يَدَيْ السَّاعَةِ وَإِنَّهُ لَيْسَ مِنْ بَلْدَةٍ إِلَّا يَبْلُغُهَا رُعْبُ ‏ ‏الْمَسِيحِ ‏ ‏إِلَّا ‏ ‏الْمَدِينَةَ ‏ ‏عَلَى كُلِّ ‏ ‏نَقْبٍ ‏ ‏مِنْ نِقَابِهَا مَلَكَانِ يَذُبَّانِ عَنْهَا رُعْبَ ‏ ‏الْمَسِيحِ ‏","","",""],[19533,19533,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏يَقُولُ أَخْبَرَنِي ‏ ‏أَبُو بَكْرَةَ ‏ ‏قَالَ ‏ ‏أَتَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏قَوْمٍ يَتَعَاطَوْنَ سَيْفًا ‏ ‏مَسْلُولًا ‏ ‏فَقَالَ لَعَنَ اللَّهُ مَنْ فَعَلَ هَذَا أَوَلَيْسَ قَدْ نَهَيْتُ عَنْ هَذَا ثُمَّ قَالَ إِذَا سَلَّ أَحَدُكُمْ سَيْفَهُ فَنَظَرَ إِلَيْهِ فَأَرَادَ أَنْ يُنَاوِلَهُ أَخَاهُ فَلْيُغْمِدْهُ ثُمَّ يُنَاوِلْهُ إِيَّاهُ ‏","","",""],[19534,19534,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْجَلِيلِ ‏ ‏حَدَّثَنِي ‏ ‏جَعْفَرُ بْنُ مَيْمُونٍ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لِأَبِيهِ ‏ ‏يَا ‏ ‏أَبَتِ إِنِّي أَسْمَعُكَ تَدْعُو كُلَّ ‏ ‏غَدَاةٍ ‏ ‏اللَّهُمَّ عَافِنِي فِي بَدَنِي اللَّهُمَّ عَافِنِي فِي سَمْعِي اللَّهُمَّ عَافِنِي فِي بَصَرِي لَا إِلَهَ إِلَّا أَنْتَ تُعِيدُهَا ثَلَاثًا حِينَ تُصْبِحُ وَثَلَاثًا حِينَ تُمْسِي وَتَقُولُ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الْكُفْرِ وَالْفَقْرِ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ لَا إِلَهَ إِلَّا أَنْتَ تُعِيدُهَا حِينَ تُصْبِحُ ثَلَاثًا وَثَلَاثًا حِينَ تُمْسِي قَالَ نَعَمْ يَا بُنَيَّ إِنِّي سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْعُو بِهِنَّ فَأُحِبُّ أَنْ أَسْتَنَّ بِسُنَّتِهِ ‏","","",""],[19535,19535,"","","‏ ‏قَالَ ‏ ‏وَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعَوَاتُ ‏ ‏الْمَكْرُوبِ ‏ ‏اللَّهُمَّ رَحْمَتَكَ أَرْجُو فَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ أَصْلِحْ لِي شَأْنِي كُلَّهُ لَا إِلَهَ إِلَّا أَنْتَ ‏","","",""],[19536,19536,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ الشَّحَّامُ ‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِرَجُلٍ سَاجِدٍ وَهُوَ يَنْطَلِقُ إِلَى الصَّلَاةِ فَقَضَى الصَّلَاةَ وَرَجَعَ عَلَيْهِ وَهُوَ سَاجِدٌ فَقَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مَنْ يَقْتُلُ هَذَا فَقَامَ رَجُلٌ ‏ ‏فَحَسَرَ ‏ ‏عَنْ يَدَيْهِ فَاخْتَرَطَ سَيْفَهُ وَهَزَّهُ ثُمَّ قَالَ يَا نَبِيَّ اللَّهِ بِأَبِي أَنْتَ وَأُمِّي كَيْفَ أَقْتُلُ رَجُلًا سَاجِدًا يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ ثُمَّ قَالَ مَنْ يَقْتُلُ هَذَا فَقَامَ رَجُلٌ فَقَالَ أَنَا ‏ ‏فَحَسَرَ ‏ ‏عَنْ ذِرَاعَيْهِ وَاخْتَرَطَ سَيْفَهُ وَهَزَّهُ حَتَّى ‏ ‏أَرْعَدَتْ ‏ ‏يَدُهُ فَقَالَ يَا نَبِيَّ اللَّهِ كَيْفَ أَقْتُلُ رَجُلًا سَاجِدًا يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ لَوْ قَتَلْتُمُوهُ لَكَانَ أَوَّلَ ‏ ‏فِتْنَةٍ ‏ ‏وَآخِرَهَا ‏","","",""],[19537,19537,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الطَّيَالِسِيُّ أَبُو دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏عِمْرَانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَعْنِي ‏ ‏صُومُوا الْهِلَالَ لِرُؤْيَتِهِ وَأَفْطِرُوا لِرُؤْيَتِهِ فَإِنْ ‏ ‏غُمَّ ‏ ‏عَلَيْكُمْ فَأَكْمِلُوا الْعِدَّةَ ثَلَاثِينَ وَالشَّهْرُ هَكَذَا وَهَكَذَا وَهَكَذَا وَعَقَدَ ‏","","",""],[19538,19538,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدُ بْنُ مِهْرَانَ ‏ ‏حَدَّثَنَا ‏ ‏سَعْدُ بْنُ أَوْسٍ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ كُسَيْبٍ الْعَدَوِيِّ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَكْرَمَ سُلْطَانَ اللَّهِ تَبَارَكَ وَتَعَالَى فِي الدُّنْيَا أَكْرَمَهُ اللَّهُ يَوْمَ الْقِيَامَةِ وَمَنْ أَهَانَ سُلْطَانَ اللَّهِ تَبَارَكَ وَتَعَالَى فِي الدُّنْيَا أَهَانَهُ اللَّهُ يَوْمَ الْقِيَامَةِ ‏","","",""],[19539,19539,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏أَخْبَرَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏بِلَالِ بْنِ يَقْطُرَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏أُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِدَنَانِيرَ فَجَعَلَ ‏ ‏يَقْبِضُ ‏ ‏قَبْضَةً ‏ ‏قَبْضَةً ‏ ‏ثُمَّ يَنْظُرُ عَنْ يَمِينِهِ كَأَنَّهُ يُؤَامِرُ أَحَدًا ثُمَّ يُعْطِي وَرَجُلٌ أَسْوَدُ ‏ ‏مَطْمُومٌ ‏ ‏عَلَيْهِ ثَوْبَانِ أَبْيَضَانِ بَيْنَ عَيْنَيْهِ أَثَرُ السُّجُودِ فَقَالَ مَا عَدَلْتَ فِي الْقِسْمَةِ فَغَضِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ مَنْ يَعْدِلُ عَلَيْكُمْ بَعْدِي قَالُوا يَا رَسُولَ اللَّهِ أَلَا نَقْتُلُهُ فَقَالَ لَا ثُمَّ قَالَ لِأَصْحَابِهِ ‏ ‏هَذَا وَأَصْحَابُهُ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الدِّينِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏السَّهْمُ مِنْ ‏ ‏الرَّمِيَّةِ ‏ ‏لَا يَتَعَلَّقُونَ مِنْ الْإِسْلَامِ بِشَيْءٍ ‏","","",""],[19540,19540,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏بَشَّارٌ الْخَيَّاطُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الْعَزِيزِ بْنَ أَبِي بَكْرَةَ ‏ ‏يُحَدِّثُ أَنَّ ‏ ‏أَبَا بَكْرَةَ ‏ ‏جَاءَ وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَاكِعٌ ‏ ‏فَسَمِعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَوْتَ نَعْلِ ‏ ‏أَبِي بَكْرَةَ ‏ ‏وَهُوَ يَحْضُرُ يُرِيدُ أَنْ يُدْرِكَ الرَّكْعَةَ فَلَمَّا انْصَرَفَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَنْ السَّاعِي قَالَ ‏ ‏أَبُو بَكْرَةَ ‏ ‏أَنَا قَالَ زَادَكَ اللَّهُ حِرْصًا وَلَا تَعُدْ ‏","","",""],[19541,19541,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ سُلَيْمٍ الْمُقْرِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏رَجُلًا ‏ ‏يُحَدِّثُ ‏ ‏عَمْرَو بْنَ عُثْمَانَ ‏ ‏وَأَنَا شَاهِدٌ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ أَبِي بَكْرَةَ ‏ ‏يُحَدِّثُ أَنَّ ‏ ‏أَبَا بَكْرَةَ ‏ ‏حَدَّثَهُمْ أَنَّهُ ‏ ‏شَهِدَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى بَغْلَتِهِ وَاقِفًا إِذْ ‏ ‏جَاءُوا بِامْرَأَةٍ حُبْلَى فَقَالَتْ إِنَّهَا زَنَتْ ‏ ‏أَوْ بَغَتْ ‏ ‏فَارْجُمْهَا ‏ ‏فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَتِرِي بِسِتْرِ اللَّهِ عَزَّ وَجَلَّ فَرَجَعَتْ ثُمَّ جَاءَتْ الثَّانِيَةَ وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى بَغْلَتِهِ فَقَالَتْ ‏ ‏ارْجُمْهَا ‏ ‏يَا نَبِيَّ اللَّهِ فَقَالَ اسْتَتِرِي بِسِتْرِ اللَّهِ تَبَارَكَ وَتَعَالَى فَرَجَعَتْ ثُمَّ جَاءَتْ الثَّالِثَةَ وَهُوَ وَاقِفٌ حَتَّى أَخَذَتْ بِلِجَامِ بَغْلَتِهِ فَقَالَتْ أَنْشُدُكَ اللَّهَ أَلَا ‏ ‏رَجَمْتَهَا ‏ ‏فَقَالَ اذْهَبِي حَتَّى تَلِدِي فَانْطَلَقَتْ فَوَلَدَتْ غُلَامًا ثُمَّ جَاءَتْ فَكَلَّمَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ لَهَا اذْهَبِي فَتَطَهَّرِي مِنْ الدَّمِ فَانْطَلَقَتْ ثُمَّ أَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ إِنَّهَا قَدْ تَطَهَّرَتْ فَأَرْسَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِسْوَةً فَأَمَرَهُنَّ أَنْ ‏ ‏يَسْتَبْرِئْنَ ‏ ‏الْمَرْأَةَ فَجِئْنَ وَشَهِدْنَ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِطُهْرِهَا فَأَمَرَ لَهَا ‏ ‏بِحُفَيْرَةٍ إِلَى ‏ ‏ثَنْدُوَتِهَا ‏ ‏ثُمَّ جَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْمُسْلِمُونَ فَأَخَذَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَصَاةً مِثْلَ الْحِمَّصَةِ فَرَمَاهَا ثُمَّ مَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ لِلْمُسْلِمِينَ ارْمُوهَا وَإِيَّاكُمْ وَوَجْهَهَا فَلَمَّا ‏ ‏طَفِئَتْ ‏ ‏أَمَرَ بِإِخْرَاجِهَا فَصَلَّى عَلَيْهَا ثُمَّ قَالَ لَوْ قُسِّمَ أَجْرُهَا بَيْنَ أَهْلِ ‏ ‏الْحِجَازِ ‏ ‏وَسِعَهُمْ ‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏زَكَرِيَّا أَبُو عِمْرَانَ الْبَصْرِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏شَيْخًا ‏ ‏يُحَدِّثُ ‏ ‏عَمْرَو بْنَ عُثْمَانَ الْقُرَشِيَّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرَةَ ‏ ‏فَذَكَرَ الْحَدِيثَ إِلَّا أَنَّهُ قَالَ فَكَفَلَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ لَوْ قُسِّمَ أَجْرُهَا بَيْنَ أَهْلِ ‏ ‏الْحِجَازِ ‏ ‏لَوَسِعَهُمْ ‏","","",""],[19542,19542,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَنَّ رَجُلًا مِنْ أَهْلِ ‏ ‏فَارِسَ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ رَبِّي تَبَارَكَ وَتَعَالَى قَدْ قَتَلَ رَبَّكَ ‏ ‏يَعْنِي ‏ ‏كِسْرَى ‏ ‏قَالَ وَقِيلَ لَهُ ‏ ‏يَعْنِي لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ قَدْ اسْتَخْلَفَ ابْنَتَهُ قَالَ فَقَالَ ‏ ‏لَا يُفْلِحُ قَوْمٌ تَمْلِكُهُمْ امْرَأَةٌ ‏","","",""],[19543,19543,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلُ بْنُ إِسْمَاعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمُعَلَّى بْنُ زِيَادٍ ‏ ‏وَيُونُسُ ‏ ‏وَأَيُّوبُ ‏ ‏وَهِشَامٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنِ ‏ ‏الْأَحْنَفِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَوَاجَهَ الْمُسْلِمَانِ بِسَيْفَيْهِمَا فَقَتَلَ أَحَدُهُمَا صَاحِبَهُ فَالْقَاتِلُ وَالْمَقْتُولُ فِي النَّارِ قِيلَ هَذَا الْقَاتِلُ فَمَا بَالَ الْمَقْتُولِ قَالَ قَدْ أَرَادَ قَتْلَ صَاحِبِهِ ‏","","",""],[19544,19544,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ زَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سُلَيْمَانَ الْعَصَرِيَّ ‏ ‏حَدَّثَنِي ‏ ‏عُقْبَةُ بْنُ صُهْبَانَ ‏ ‏قَالَ سَمِعْتْ ‏ ‏أَبَا بَكْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُحْمَلُ النَّاسُ عَلَى الصِّرَاطِ يَوْمَ الْقِيَامَةِ ‏ ‏فَتَقَادَعُ ‏ ‏بِهِمْ جَنَبَةُ الصِّرَاطِ ‏ ‏تَقَادُعَ ‏ ‏الْفَرَاشِ فِي النَّارِ قَالَ ‏ ‏فَيُنْجِي اللَّهُ تَبَارَكَ وَتَعَالَى بِرَحْمَتِهِ مَنْ يَشَاءُ قَالَ ثُمَّ يُؤْذَنُ لِلْمَلَائِكَةِ وَالنَّبِيِّينَ وَالشُّهَدَاءِ أَنْ يَشْفَعُوا فَيَشْفَعُونَ وَيُخْرِجُونَ وَيَشْفَعُونَ وَيُخْرِجُونَ وَيَشْفَعُونَ وَيُخْرِجُونَ ‏ ‏وَزَادَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً فَقَالَ أَيْضًا وَيَشْفَعُونَ وَيُخْرِجُونَ ‏ ‏مَنْ كَانَ فِي قَلْبِهِ مَا يَزِنُ ذَرَّةً مِنْ إِيمَانٍ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبَانَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ زَيْدٍ ‏ ‏مِثْلَهُ ‏","","",""],[19545,19545,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَدْخُلُ ‏ ‏الْمَدِينَةَ ‏ ‏رُعْبُ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏ ‏لَهَا يَوْمَئِذٍ سَبْعَةُ أَبْوَابٍ عَلَى كُلِّ بَابٍ مِنْهَا مَلَكَانِ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[19546,19546,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَجُلًا قَالَ يَا رَسُولَ اللَّهِ ‏ ‏أَيُّ النَّاسِ خَيْرٌ قَالَ مَنْ طَالَ عُمْرُهُ وَحَسُنَ عَمَلُهُ قَالَ فَأَيُّ النَّاسِ ‏ ‏شَرٌّ قَالَ مَنْ طَالَ عُمْرُهُ وَسَاءَ عَمَلُهُ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ يَعْنِي ابْنَ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏وَحُمَيْدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[19547,19547,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏وَفَدْتُ مَعَ أَبِي إِلَى ‏ ‏مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏فَأُدْخِلْنَا عَلَيْهِ فَقَالَ يَا ‏ ‏أَبَا بَكْرَةَ ‏ ‏حَدِّثْنِي بِشَيْءٍ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْجِبُهُ الرُّؤْيَا الصَّالِحَةُ وَيَسْأَلُ عَنْهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ ‏ ‏أَيُّكُمْ رَأَى رُؤْيَا فَقَالَ رَجُلٌ أَنَا يَا رَسُولَ اللَّهِ رَأَيْتُ كَأَنَّ مِيزَانًا دُلِّيَ مِنْ السَّمَاءِ فَوُزِنْتَ أَنْتَ ‏ ‏بِأَبِي بَكْرٍ ‏ ‏فَرَجَحْتَ ‏ ‏بِأَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏ثُمَّ وُزِنَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏بِعُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَرَجَحَ ‏ ‏أَبُو بَكْرٍ ‏ ‏بِعُمَرَ ‏ ‏ثُمَّ وُزِنَ ‏ ‏عُمَرُ ‏ ‏بِعُثْمَانَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَرَجَحَ ‏ ‏عُمَرُ ‏ ‏بِعُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمْ ‏ ‏ثُمَّ رُفِعَ الْمِيزَانُ فَاسْتَاءَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ خِلَافَةُ نُبُوَّةٍ ثُمَّ يُؤْتِي اللَّهُ تَبَارَكَ وَتَعَالَى الْمُلْكَ مَنْ يَشَاءُ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِيهِ فَاسْتَاءَ لَهَا ‏ ‏قَالَ وَقَالَ ‏ ‏حَمَّادٌ ‏ ‏فَسَاءَهُ ذَلِكَ ‏","","",""],[19548,19548,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ الشَّحَّامُ ‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ أَبِي بَكْرَةَ ‏ ‏وَسَأَلَهُ هَلْ سَمِعْتَ فِي ‏ ‏الْخَوَارِجِ ‏ ‏مِنْ شَيْءٍ ‏ ‏فَقَالَ سَمِعْتُ ‏ ‏وَالِدِي ‏ ‏أَبَا بَكْرَةَ ‏ ‏يَقُولُ ‏ ‏عَنْ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا إِنَّهُ ‏ ‏سَيَخْرُجُ مِنْ أُمَّتِي أَقْوَامٌ أَشِدَّاءُ ‏ ‏أَحِدَّاءُ ‏ ‏ذَلِقَةٌ ‏ ‏أَلْسِنَتُهُمْ بِالْقُرْآنِ لَا ‏ ‏يُجَاوِزُ ‏ ‏تَرَاقِيَهُمْ ‏ ‏أَلَا فَإِذَا رَأَيْتُمُوهُمْ ‏ ‏فَأَنِيمُوهُمْ ‏ ‏ثُمَّ إِذَا رَأَيْتُمُوهُمْ ‏ ‏فَأَنِيمُوهُمْ ‏ ‏فَالْمَأْجُورُ قَاتِلُهُمْ ‏","","",""],[19549,19549,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ الشَّحَّامُ ‏ ‏حَدَّثَنِي ‏ ‏مُسْلِمُ بْنُ أَبِي بَكْرَةَ ‏ ‏أَنَّهُ ‏ ‏مَرَّ ‏ ‏بِوَالِدِهِ ‏ ‏وَهُوَ يَدْعُو وَيَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الْكُفْرِ وَالْفَقْرِ وَعَذَابِ الْقَبْرِ قَالَ فَأَخَذْتُهُنَّ عَنْهُ وَكُنْتُ أَدْعُو بِهِنَّ فِي دُبُرِ كُلِّ صَلَاةٍ قَالَ فَمَرَّ بِي وَأَنَا أَدْعُو بِهِنَّ فَقَالَ يَا بُنَيَّ أَنَّى عَقَلْتَ هَؤُلَاءِ الْكَلِمَاتِ قَالَ يَا أَبَتَاهُ سَمِعْتُكَ تَدْعُو بِهِنَّ فِي دُبُرِ كُلِّ صَلَاةٍ فَأَخَذْتُهُنَّ عَنْكَ قَالَ فَالْزَمْهُنَّ يَا بُنَيَّ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَدْعُو بِهِنَّ فِي دُبُرِ كُلِّ صَلَاةٍ ‏","","",""],[19550,19550,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي بِالنَّاسِ وَكَانَ ‏ ‏الْحَسَنُ بْنُ عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏يَثِبُ ‏ ‏عَلَى ظَهْرِهِ إِذَا سَجَدَ فَفَعَلَ ذَلِكَ غَيْرَ مَرَّةٍ فَقَالُوا لَهُ وَاللَّهِ إِنَّكَ لَتَفْعَلُ بِهَذَا شَيْئًا مَا رَأَيْنَاكَ تَفْعَلُهُ بِأَحَدٍ قَالَ الْمُبَارَكُ فَذَكَرَ شَيْئًا ثُمَّ قَالَ ‏ ‏إِنَّ ابْنِي هَذَا سَيِّدٌ وَسَيُصْلِحُ اللَّهُ تَبَارَكَ وَتَعَالَى بِهِ بَيْنَ فِئَتَيْنِ مِنْ الْمُسْلِمِينَ ‏ ‏فَقَالَ ‏ ‏الْحَسَنُ ‏ ‏فَوَاللَّهِ وَاللَّهِ بَعْدَ أَنْ وَلِيَ لَمْ ‏ ‏يُهْرَقْ ‏ ‏فِي خِلَافَتِهِ مِلْءُ مِحْجَمَةٍ مِنْ دَمٍ ‏","","",""],[19551,19551,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ عُبَيْدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏وَعَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَلَا ‏ ‏لَا تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ‏ ‏وَقَالَ ‏ ‏ابْنُ سِيرِينَ ‏ ‏ضُلَّالًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ‏","","",""],[19552,19552,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ رَبِّهِ بْنِ سَعِيدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَوْلًى ‏ ‏لِآلِ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏يُكَنَّى ‏ ‏أَبَا عَبْدِ اللَّهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ أَبِي الْحَسَنِ الْبَصْرِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَنَّهُ دُعِيَ إِلَى شَهَادَةٍ مَرَّةً فَجَاءَ إِلَى الْبَيْتِ فَقَامَ لَهُ رَجُلٌ مِنْ مَجْلِسِهِ فَقَالَ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ الرَّجُلُ لِلرَّجُلِ مِنْ مَجْلِسِهِ أَنْ يَجْلِسَ فِيهِ ‏ ‏وَأَنْ ‏ ‏يَمْسَحَ الرَّجُلُ يَدَهُ بِثَوْبِ مَنْ لَا يَمْلِكُ ‏","","",""],[19553,19553,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَشْرَجُ ابْنُ نُبَاتَةَ الْقَيْسِيُّ الْكُوفِيُّ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ جُمْهَانَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي بَكْرَةَ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏فِي هَذَا الْمَسْجِدِ ‏ ‏يَعْنِي ‏ ‏مَسْجِدَ ‏ ‏الْبَصْرَةِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَتَنْزِلَنَّ طَائِفَةٌ مِنْ أُمَّتِي أَرْضًا يُقَالُ لَهَا ‏ ‏الْبَصْرَةُ ‏ ‏يَكْثُرُ بِهَا عَدَدُهُمْ وَيَكْثُرُ بِهَا نَخْلُهُمْ ثُمَّ يَجِيءُ ‏ ‏بَنُو قَنْطُورَاءَ ‏ ‏عِرَاضُ الْوُجُوهِ صِغَارُ الْعُيُونِ حَتَّى يَنْزِلُوا عَلَى جِسْرٍ لَهُمْ يُقَالُ لَهُ دِجْلَةُ فَيَتَفَرَّقُ الْمُسْلِمُونَ ثَلَاثَ فِرَقٍ فَأَمَّا فِرْقَةٌ فَيَأْخُذُونَ بِأَذْنَابِ الْإِبِلِ وَتَلْحَقُ بِالْبَادِيَةِ وَهَلَكَتْ وَأَمَّا فِرْقَةٌ فَتَأْخُذُ عَلَى أَنْفُسِهَا فَكَفَرَتْ فَهَذِهِ وَتِلْكَ سَوَاءٌ وَأَمَّا فِرْقَةٌ فَيَجْعَلُونَ عِيَالَهُمْ خَلْفَ ظُهُورِهِمْ وَيُقَاتِلُونَ فَقَتْلَاهُمْ شُهَدَاءُ وَيَفْتَحُ اللَّهُ عَلَى بَقِيَّتِهَا ‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَشْرَجٌ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَوْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي بَكْرَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏فِي هَذَا الْمَسْجِدِ ‏ ‏يَعْنِي مَسْجِدَ ‏ ‏الْبَصْرَةِ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[19554,19554,"","","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ بْنُ خَلِيفَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ ذَاكَ الْيَوْمُ رَكِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَاقَتَهُ ثُمَّ وَقَفَ فَقَالَ تَدْرُونَ أَيُّ يَوْمٍ هَذَا فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏ابْنِ أَبِي عَدِيٍّ ‏ ‏وَقَالَ فِيهِ ‏ ‏أَلَا لِيُبَلِّغْ الشَّاهِدُ الْغَائِبَ مَرَّتَيْنِ فَرُبَّ مُبَلَّغٍ هُوَ ‏ ‏أَوْعَى ‏ ‏مِنْ مُبَلِّغٍ مِثْلَهُ ثُمَّ مَالَ عَلَى نَاقَتِهِ إِلَى غُنَيْمَاتٍ فَجَعَلَ يَقْسِمُهُنَّ بَيْنَ الرَّجُلَيْنِ الشَّاةُ وَالثَّلَاثَةِ الشَّاةُ ‏","","",""],[19555,19555,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حَمَّادَ بْنَ سَلَمَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏وَحُمَيْدٍ ‏ ‏فِي آخَرِينَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى سَيُؤَيِّدُ هَذَا الدِّينَ بِأَقْوَامٍ لَا ‏ ‏خَلَاقَ ‏ ‏لَهُمْ ‏","","",""],[19556,19556,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ الْحَرَّانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرَةَ بَكَّارُ بْنُ عَبْدِ الْعَزِيزِ بْنِ أَبِي بَكْرَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَنَّهُ شَهِدَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَاهُ بَشِيرٌ يُبَشِّرُهُ بِظَفَرِ جُنْدٍ لَهُ عَلَى عَدُوِّهِمْ وَرَأْسُهُ فِي حِجْرِ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏فَقَامَ فَخَرَّ سَاجِدًا ثُمَّ ‏ ‏أَنْشَأَ ‏ ‏يُسَائِلُ الْبَشِيرَ فَأَخْبَرَهُ فِيمَا أَخْبَرَهُ أَنَّهُ وَلِيَ أَمْرَهُمْ امْرَأَةٌ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْآنَ هَلَكَتْ الرِّجَالُ إِذَا أَطَاعَتْ النِّسَاءَ هَلَكَتْ الرِّجَالُ إِذَا أَطَاعَتْ النِّسَاءَ ثَلَاثًا ‏","","",""],[19557,19557,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏بَكَّارٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سَمَّعَ سَمَّعَ اللَّهُ بِهِ وَمَنْ ‏ ‏رَايَا ‏ ‏رَايَا اللَّهُ بِهِ ‏","","",""],[19558,19558,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏زِيَادٌ الْأَعْلَمُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَنَّهُ ‏ ‏جَاءَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَاكِعٌ فَرَكَعَ دُونَ الصَّفِّ ثُمَّ مَشَى إِلَى الصَّفِّ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ هَذَا الَّذِي رَكَعَ ثُمَّ مَشَى إِلَى الصَّفِّ فَقَالَ ‏ ‏أَبُو بَكْرَةَ ‏ ‏أَنَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَادَكَ اللَّهُ حِرْصًا وَلَا تَعُدْ ‏","","",""],[19559,19559,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏أَخْبَرَنَا ‏ ‏زِيَادٌ الْأَعْلَمُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَنَّهُ ‏ ‏دَخَلَ الْمَسْجِدَ وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَاكِعٌ ‏ ‏فَرَكَعَ قَبْلَ أَنْ يَصِلَ إِلَى الصَّفِّ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَادَكَ اللَّهُ حِرْصًا وَلَا تَعُدْ ‏","","",""],[19560,19560,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏زِيَادٌ الْأَعْلَمُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ فِي صَلَاةِ الْفَجْرِ ‏ ‏فَأَوْمَأَ ‏ ‏إِلَى أَصْحَابِهِ أَيْ مَكَانَكُمْ فَذَهَبَ وَجَاءَ وَرَأْسُهُ يَقْطُرُ فَصَلَّى بِالنَّاسِ ‏","","",""],[19561,19561,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ مُعَاذٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنِي ‏ ‏فُضَيْلُ بْنُ فَضَالَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏رَأَى ‏ ‏أَبُو بَكْرَةَ ‏ ‏نَاسًا ‏ ‏يُصَلُّونَ الضُّحَى فَقَالَ إِنَّهُمْ لَيُصَلُّونَ صَلَاةً مَا صَلَّاهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا عَامَّةُ أَصْحَابِهِ ‏ ‏رَضِيَ اللَّهُ عَنْهُمْ ‏","","",""],[19562,19562,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏وَمُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ‏","","",""],[19563,19563,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏وَيَزِيدُ يَعْنِي ابْنَ زُرَيْعٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏مَدَحَ رَجُلٌ رَجُلًا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيْلَكَ قَطَعْتَ عُنُقَ صَاحِبِكَ مِرَارًا إِذَا كَانَ أَحَدُكُمْ مَادِحًا صَاحِبَهُ لَا مَحَالَةَ فَلْيَقُلْ أَحْسَبُ فُلَانًا وَاللَّهُ ‏ ‏حَسِيبُهُ ‏ ‏وَلَا أُزَكِّي عَلَى اللَّهِ تَبَارَكَ وَتَعَالَى أَحَدًا إِنْ كَانَ يَعْلَمُ ذَاكَ أَحْسَبُهُ كَذَا وَكَذَا ‏","","",""],[19564,19564,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْخَذْفِ ‏ ‏فَأَخَذَ ابْنُ عَمٍّ لَهُ فَقَالَ عَنْ هَذَا ‏ ‏وَخَذَفَ ‏ ‏فَقَالَ أَلَا أُرَانِي أُخْبِرُكَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْهُ وَأَنْتَ ‏ ‏تَخْذِفُ ‏ ‏وَاللَّهِ لَا أُكَلِّمُكَ ‏ ‏عَزْمَةً ‏ ‏مَا عِشْتُ ‏ ‏أَوْ مَا بَقِيتُ أَوْ نَحْوَ هَذَا ‏","","",""],[19565,19565,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ عَبْدِ اللَّهِ بْنِ عَوْفٍ ‏ ‏أَنَّ ‏ ‏عِيَاضَ بْنَ مُسَافِعٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَخِي ‏ ‏زِيَادٍ ‏ ‏لِأُمِّهِ ‏ ‏قَالَ ‏ ‏أَبُو بَكْرَةَ ‏ ‏أَكْثَرَ النَّاسُ فِي شَأْنِ ‏ ‏مُسَيْلِمَةَ ‏ ‏الْكَذَّابِ قَبْلَ أَنْ يَقُولَ فِيهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَيْئًا ثُمَّ قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي النَّاسِ فَأَثْنَى عَلَى اللَّهِ تَبَارَكَ وَتَعَالَى بِمَا هُوَ أَهْلُهُ ثُمَّ قَالَ ‏ ‏أَمَّا بَعْدُ فَإِنَّ شَأْنَ هَذَا الرَّجُلِ الَّذِي قَدْ أَكْثَرْتُمْ فِي شَأْنِهِ فَإِنَّهُ كَذَّابٌ مِنْ ثَلَاثِينَ كَذَّابًا يَخْرُجُونَ قَبْلَ ‏ ‏الدَّجَّالِ ‏ ‏وَإِنَّهُ لَيْسَ بَلَدٌ إِلَّا يَدْخُلُهُ رُعْبُ ‏ ‏الْمَسِيحِ ‏ ‏إِلَّا ‏ ‏الْمَدِينَةَ ‏ ‏عَلَى كُلِّ ‏ ‏نَقْبٍ ‏ ‏مِنْ نِقَابِهَا يَوْمَئِذٍ مَلَكَانِ يَذُبَّانِ عَنْهَا رُعْبَ ‏ ‏الْمَسِيحِ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَخِي ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَخْبَرَنِي ‏ ‏طَلْحَةُ بْنُ عَبْدِ اللَّهِ بْنِ عَوْفٍ ‏ ‏أَنَّ ‏ ‏عِيَاضَ بْنَ مُسَافِعٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أَبَا بَكْرَةَ ‏ ‏أَخَا ‏ ‏زِيَادٍ ‏ ‏لِأُمِّهِ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو بَكْرَةَ ‏ ‏أَكْثَرَ النَّاسُ فِي شَأْنِ ‏ ‏مُسَيْلِمَةَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[19566,19566,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏قَالَ ‏ ‏لَمَّا ادَّعَى ‏ ‏زِيَادٌ ‏ ‏لَقِيتُ ‏ ‏أَبَا بَكْرَةَ ‏ ‏فَقُلْتُ مَا هَذَا الَّذِي صَنَعْتُمْ إِنِّي ‏ ‏سَمِعْتُ ‏ ‏سَعْدَ بْنَ أَبِي وَقَّاصٍ ‏ ‏يَقُولُ ‏ ‏سَمِعَتْ أُذُنَايَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَقُولُ ‏ ‏مَنْ ادَّعَى أَبًا فِي الْإِسْلَامِ غَيْرَ أَبِيهِ فَالْجَنَّةُ عَلَيْهِ حَرَامٌ فَقَالَ ‏ ‏أَبُو بَكْرَةَ ‏ ‏وَأَنَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[19567,19567,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مُحَمَّدٍ الْمُحَارِبِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ أَبِي بَكْرَةَ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏أَمَرَهُ أَنْ يَكْتُبَ إِلَى ابْنٍ لَهُ وَكَانَ قَاضِيًا ‏ ‏بِسِجِسْتَانَ ‏ ‏أَمَّا بَعْدُ فَلَا تَحْكُمَنَّ بَيْنَ اثْنَيْنِ وَأَنْتَ غَضْبَانُ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَحْكُمْ أَحَدٌ بَيْنَ اثْنَيْنِ وَهُوَ غَضْبَانُ ‏","","",""],[19568,19568,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَدَحَ رَجُلٌ رَجُلًا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَطَعْتَ ظَهْرَهُ إِذَا كَانَ أَحَدُكُمْ مَادِحًا صَاحِبَهُ لَا مَحَالَةَ فَلْيَقُلْ أَحْسَبُهُ وَاللَّهُ ‏ ‏حَسِيبُهُ ‏ ‏وَلَا أَعْذِرُ عَلَى اللَّهِ أَحَدًا أَحْسَبُهُ كَذَا وَكَذَا إِنْ كَانَ يَعْلَمُ ذَلِكَ مِنْهُ ‏","","",""],[19569,19569,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَغَيْرِ وَاحِدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ رِيحَ الْجَنَّةِ يُوجَدُ مِنْ مَسِيرَةِ مِائَةِ عَامٍ وَمَا مِنْ عَبْدٍ يَقْتُلُ نَفْسًا ‏ ‏مُعَاهَدَةً ‏ ‏إِلَّا حَرَّمَ اللَّهُ تَبَارَكَ وَتَعَالَى عَلَيْهِ الْجَنَّةَ وَرَائِحَتَهَا أَنْ يَجِدَهَا ‏ ‏قَالَ ‏ ‏أَبُو بَكْرَةَ ‏ ‏أَصَمَّ اللَّهُ أُذُنِي إِنْ لَمْ أَكُنْ سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُهَا ‏","","",""],[19570,19570,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرَةَ ‏ ‏دَخَلَ الْمَسْجِدَ وَالْإِمَامُ رَاكِعٌ ‏ ‏فَرَكَعَ قَبْلَ أَنْ يَصِلَ إِلَى الصَّفِّ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَادَكَ اللَّهُ حِرْصًا وَلَا تَعُدْ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏هِشَامًا ‏ ‏يُحَدِّثُ عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏مِثْلَهُ ‏","","",""],[19571,19571,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَوَاجَهَ الْمُسْلِمَانِ بِسَيْفَيْهِمَا فَقَتَلَ أَحَدُهُمَا صَاحِبَهُ فَالْقَاتِلُ وَالْمَقْتُولُ فِي النَّارِ قَالُوا يَا رَسُولَ اللَّهِ هَذَا الْقَاتِلُ فَمَا بَالُ الْمَقْتُولِ قَالَ إِنَّهُ كَانَ يُرِيدُ قَتْلَ صَاحِبِهِ ‏","","",""],[19572,19572,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏أَخْبَرَنِي ‏ ‏مَنْ ‏ ‏سَمِعَ ‏ ‏الْحَسَنَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحَدِّثُنَا يَوْمًا ‏ ‏وَالْحَسَنُ بْنُ عَلِيٍّ ‏ ‏فِي حِجْرِهِ فَيُقْبِلُ عَلَى أَصْحَابِهِ فَيُحَدِّثُهُمْ ثُمَّ يُقْبِلُ عَلَى ‏ ‏الْحَسَنِ ‏ ‏فَيُقَبِّلُهُ ثُمَّ قَالَ ‏ ‏إِنَّ ابْنِي هَذَا لَسَيِّدٌ إِنْ يَعِشْ يُصْلِحْ بَيْنَ طَائِفَتَيْنِ مِنْ الْمُسْلِمِينَ ‏","","",""],[19573,19573,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُيَيْنَةُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَنْ يُفْلِحَ قَوْمٌ أَسْنَدُوا أَمْرَهُمْ إِلَى امْرَأَةٍ ‏","","",""],[19574,19574,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعْدُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَدْخُلُ ‏ ‏الْمَدِينَةَ ‏ ‏رُعْبُ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏ ‏لَهَا يَوْمَئِذٍ سَبْعَةُ أَبْوَابٍ لِكُلِّ بَابٍ مَلَكَانِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ عَبْدِ اللَّهِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ أَكْثَرَ النَّاسُ فِي شَأْنِ ‏ ‏مُسَيْلِمَةَ ‏ ‏فَذَكَرَ نَحْوَ حَدِيثِ ‏ ‏عُقَيْلٍ ‏","","",""],[19575,19575,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏عُيَيْنَةُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُفْلِحُ قَوْمٌ أَسْنَدُوا أَمْرَهُمْ إِلَى امْرَأَةٍ ‏","","",""],[19576,19576,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏مُبَارَكُ بْنُ فَضَالَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُفْلِحُ قَوْمٌ تَمْلِكُهُمْ امْرَأَةٌ ‏","","",""],[19577,19577,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏وَرَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ أَبِي حَاتِمٍ ‏ ‏وَقَالَ ‏ ‏رَوْحٌ ‏ ‏عَنْ ‏ ‏سَالِمٍ أَبِي عُبَيْدِ اللَّهِ بْنِ سَالِمٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثٍ ذَكَرَهُ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ أَبِي عُبَيْدِ اللَّهِ ‏ ‏وَهُوَ أَيْضَا ‏ ‏يُكَنَّى ‏ ‏أَبَا حَاتِمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏شَهْرَا عِيدٍ لَا يَنْقُصَانِ رَمَضَانُ وَذُو الْحِجَّةِ ‏","","",""],[19578,19578,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ النَّاسِ أَفْضَلُ ‏ ‏أَوْ قَالَ خَيْرٌ شَكَّ ‏ ‏يَزِيدُ ‏ ‏قَالَ مَنْ طَالَ عُمْرُهُ وَحَسُنَ عَمَلُهُ قِيلَ فَأَيُّ النَّاسِ شَرٌّ قَالَ مَنْ طَالَ عُمْرُهُ وَسَاءَ عَمَلُهُ ‏","","",""],[19579,19579,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَنَّ رَجُلًا قَالَ يَا رَسُولَ اللَّهِ ‏ ‏أَيُّ النَّاسِ خَيْرٌ قَالَ مَنْ طَالَ عُمْرُهُ وَحَسُنَ عَمَلُهُ قِيلَ فَأَيُّ النَّاسِ شَرٌّ قَالَ مَنْ طَالَ عُمْرُهُ وَسَاءَ عَمَلُهُ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[19580,19580,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏وَأَبُو دَاوُدَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏أَخَّرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعِشَاءَ ‏ ‏سَبْعَ ‏ ‏لَيَالٍ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُدَ ‏ ‏ثَمَانِ لَيَالٍ ‏ ‏إِلَى ثُلُثِ اللَّيْلِ فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَا رَسُولَ اللَّهِ لَوْ أَنَّكَ عَجَّلْتَ لَكَانَ أَمْثَلَ لِقِيَامِنَا مِنْ اللَّيْلِ قَالَ فَعَجَّلَ بَعْدَ ذَلِكَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَحَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏فَقَالَ ‏ ‏فِي حَدِيثِهِ سَبْعَ لَيَالٍ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏تِسْعَ لَيَالٍ ‏","","",""],[19581,19581,"","","‏ ‏حَدَّثَنَا ‏ ‏مَحْبُوبُ بْنُ الْحَسَنِ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏رَجُلًا مَدَحَ صَاحِبًا لَهُ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ وَيْلَكَ قَطَعْتَ عُنُقَهُ إِنْ كُنْتَ مَادِحًا لَا مَحَالَةَ فَقُلْ أَحْسَبُهُ كَذَا وَكَذَا وَاللَّهُ ‏ ‏حَسِيبُهُ ‏ ‏وَلَا أُزَكِّي عَلَى اللَّهِ تَعَالَى أَحَدًا ‏","","",""],[19582,19582,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏خَالِدًا الْحَذَّاءَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏شَهْرَانِ لَا يَنْقُصَانِ فِي كُلِّ وَاحِدٍ مِنْهُمَا عِيدٌ رَمَضَانُ وَذُو الْحِجَّةِ ‏","","",""],[19583,19583,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏شُعْبَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ رَبِّهِ بْنَ سَعِيدٍ ‏ ‏وَقَالَ ‏ ‏بَهْزٌ ‏ ‏عَبْدَ رَبِّهِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ ‏ ‏مَوْلَى ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي الْحَسَنِ ‏ ‏قَالَ ‏ ‏دَخَلَ عَلَيْنَا ‏ ‏أَبُو بَكْرَةَ ‏ ‏فِي شَهَادَةٍ فَقَامَ لَهُ رَجُلٌ مِنْ مَجْلِسِهِ فَقَالَ ‏ ‏أَبُو بَكْرَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُقِمْ الرَّجُلَ الرَّجُلَ مِنْ مَجْلِسِهِ ثُمَّ يَقْعُدُ فِيهِ ‏ ‏أَوْ قَالَ إِذَا أَقَامَ الرَّجُلُ الرَّجُلَ مِنْ مَجْلِسِهِ فَلَا يَجْلِسْ فِيهِ ‏ ‏وَلَا يَمْسَحْ الرَّجُلُ يَدَهُ بِثَوْبِ مَنْ لَا يَمْلِكُ ‏","","",""],[19584,19584,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَسْلَمُ ‏ ‏وَغِفَارُ ‏ ‏وَمُزَيْنَةُ ‏ ‏وَجُهَيْنَةُ ‏ ‏خَيْرٌ مِنْ ‏ ‏بَنِي تَمِيمٍ ‏ ‏وَبَنِي عَامِرٍ ‏","","",""],[19585,19585,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَقُولَنَّ أَحَدُكُمْ إِنِّي قُمْتُ رَمَضَانَ كُلَّهُ قَالَ فَاللَّهُ تَبَارَكَ وَتَعَالَى أَعْلَمُ أَخَشِيَ عَلَى أُمَّتِهِ أَنْ تُزَكِّيَ أَنْفُسَهَا ‏ ‏قَالَ ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏فَاللَّهُ أَعْلَمُ أَخَشِيَ التَّزْكِيَةَ عَلَى أُمَّتِهِ ‏ ‏أَوْ قَالَ لَا بُدَّ مِنْ نَوْمٍ أَوْ غَفْلَةٍ ‏","","",""],[19586,19586,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامٌ ‏ ‏وَعَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقُولَنَّ أَحَدُكُمْ قُمْتُ رَمَضَانَ كُلَّهُ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏فَاللَّهُ تَبَارَكَ وَتَعَالَى أَعْلَمُ أَخَشِيَ عَلَى أُمَّتِهِ التَّزْكِيَةَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏أَوْ قَالَ لَا بُدَّ مِنْ رَاقِدٍ أَوْ غَافِلٍ ‏","","",""],[19587,19587,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ الشَّحَّامُ ‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّهَا سَتَكُونُ ‏ ‏فِتَنٌ ‏ ‏ثُمَّ تَكُونُ ‏ ‏فِتَنٌ ‏ ‏أَلَا فَالْمَاشِي فِيهَا خَيْرٌ مِنْ السَّاعِي إِلَيْهَا أَلَا وَالْقَاعِدُ فِيهَا خَيْرٌ مِنْ الْقَائِمِ فِيهَا أَلَا وَالْمُضْطَجِعُ فِيهَا خَيْرٌ مِنْ الْقَاعِدِ أَلَا فَإِذَا نَزَلَتْ فَمَنْ كَانَتْ لَهُ غَنَمٌ فَلْيَلْحَقْ بِغَنَمِهِ أَلَا وَمَنْ كَانَتْ لَهُ أَرْضٌ فَلْيَلْحَقْ بِأَرْضِهِ أَلَا وَمَنْ كَانَتْ لَهُ إِبِلٌ فَلْيَلْحَقْ بِإِبِلِهِ فَقَالَ رَجُلٌ مِنْ الْقَوْمِ يَا نَبِيَّ اللَّهِ جَعَلَنِي اللَّهُ فِدَاءَكَ أَرَأَيْتَ مَنْ لَيْسَتْ لَهُ غَنَمٌ وَلَا أَرْضٌ وَلَا إِبِلٌ كَيْفَ يَصْنَعُ قَالَ لِيَأْخُذْ سَيْفَهُ ثُمَّ لِيَعْمِدْ بِهِ إِلَى صَخْرَةٍ ثُمَّ لِيَدُقَّ عَلَى ‏ ‏حَدِّهِ ‏ ‏بِحَجَرٍ ثُمَّ لِيَنْجُ إِنْ اسْتَطَاعَ النَّجَاءَ اللَّهُمَّ هَلْ بَلَّغْتُ اللَّهُمَّ هَلْ بَلَّغْتُ إِذْ قَالَ رَجُلٌ يَا نَبِيَّ اللَّهِ جَعَلَنِي اللَّهُ فِدَاءَكَ أَرَأَيْتَ إِنْ أُخِذَ بِيَدِي مُكْرَهًا حَتَّى يُنْطَلَقَ بِي إِلَى أَحَدِ الصَّفَّيْنِ ‏ ‏أَوْ إِحْدَى الْفِئَتَيْنِ ‏ ‏عُثْمَانُ ‏ ‏يَشُكُّ ‏ ‏فَيَجْذِفَنِي رَجُلٌ بِسَيْفِهِ فَيَقْتُلَنِي مَاذَا يَكُونُ مِنْ شَأْنِي قَالَ ‏ ‏يَبُوءُ ‏ ‏بِإِثْمِكَ وَإِثْمِهِ وَيَكُونُ مِنْ أَصْحَابِ النَّارِ ‏","","",""],[19588,19588,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ أَبِي بَكْرَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ ‏ ‏أَيُّ النَّاسِ خَيْرٌ قَالَ مَنْ طَالَ عُمْرُهُ وَحَسُنَ عَمَلُهُ قِيلَ يَا رَسُولَ اللَّهِ أَيُّ النَّاسِ شَرٌّ قَالَ مَنْ طَالَ عُمْرُهُ وَسَاءَ عَمَلُهُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ النَّاسِ خَيْرٌ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[19589,19589,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ أَبُو عُثْمَانَ الشَّحَّامُ ‏ ‏فِي ‏ ‏مُرَبَّعَةِ ‏ ‏الْأَحْنَفِ ‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا اقْتَتَلَ الْمُسْلِمَانِ فَالْقَاتِلُ وَالْمَقْتُولُ فِي النَّارِ ‏","","",""],[19590,19590,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيَرِدَنَّ عَلَيَّ الْحَوْضَ رِجَالٌ مِمَّنْ صَحِبَنِي وَرَآنِي حَتَّى إِذَا رُفِعُوا إِلَيَّ وَرَأَيْتُهُمْ ‏ ‏اخْتُلِجُوا ‏ ‏دُونِي فَلَأَقُولَنَّ رَبِّ أَصْحَابِي أَصْحَابِي فَيُقَالُ إِنَّكَ لَا تَدْرِي مَا أَحْدَثُوا بَعْدَكَ ‏","","",""],[19591,19591,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدُ بْنُ مِهْرَانَ الْكِنْدِيُّ ‏ ‏حَدَّثَنِي ‏ ‏سَعْدُ بْنُ أَوْسٍ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ كُسَيْبٍ الْعَدَوِيِّ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَكْرَمَ سُلْطَانَ اللَّهِ فِي الدُّنْيَا أَكْرَمَهُ اللَّهُ يَوْمَ الْقِيَامَةِ وَمَنْ أَهَانَ سُلْطَانَ اللَّهِ فِي الدُّنْيَا أَهَانَهُ اللَّهُ يَوْمَ الْقِيَامَةِ ‏","","",""],[19592,19592,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَبِي إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرَةَ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو بَكْرَةَ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏نَبْتَاعَ ‏ ‏الْفِضَّةَ بِالْفِضَّةِ وَالذَّهَبَ بِالذَّهَبِ إِلَّا سَوَاءً بِسَوَاءٍ وَأَمَرَنَا أَنْ ‏ ‏نَبْتَاعَ ‏ ‏الْفِضَّةَ فِي الذَّهَبِ وَالذَّهَبَ فِي الْفِضَّةِ كَيْفَ شِئْنَا ‏ ‏فَقَالَ ‏ ‏لَهُ ‏ ‏ثَابِتُ بْنُ عَبْدِ اللَّهِ ‏ ‏يَدًا بِيَدٍ فَقَالَ هَكَذَا سَمِعْتُ ‏","","",""],[19593,19593,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏أَشْعَثُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏صَلَّى بِنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الْخَوْفِ فَصَلَّى بِبَعْضِ أَصْحَابِهِ رَكْعَتَيْنِ ثُمَّ سَلَّمَ فَتَأَخَّرُوا وَجَاءَ آخَرُونَ فَكَانُوا فِي مَكَانِهِمْ فَصَلَّى بِهِمْ رَكْعَتَيْنِ ثُمَّ سَلَّمَ فَصَارَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَعُ رَكَعَاتِ وَلِلْقَوْمِ رَكْعَتَانِ رَكْعَتَانِ ‏","","",""],[19594,19594,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏قُرَّةُ بْنُ خَالِدٍ ‏ ‏عَن ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرَةَ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏وَرَجُلٌ فِي نَفْسِي أَفْضَلُ مِنْ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏حُمَيْدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَن ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏خَطَبَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ النَّحْرِ ‏ ‏فَقَالَ أَيُّ يَوْمٍ هَذَا ‏ ‏أَوْ قَالَ أَتَدْرُونَ أَيُّ يَوْمٍ هَذَا ‏ ‏قَالَ قُلْنَا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ فَسَكَتَ حَتَّى ظَنَنَّا أَنَّهُ سَيُسَمِّيهِ بِغَيْرِ اسْمِهِ ثُمَّ قَالَ أَلَيْسَ ‏ ‏يَوْمَ النَّحْرِ ‏ ‏قَالَ قُلْنَا بَلَى قَالَ فَأَيُّ شَهْرٍ هَذَا ‏ ‏أَوْ قَالَ ‏ ‏أَوَ تَدْرُونَ أَيُّ شَهْرٍ هَذَا ‏ ‏قُلْنَا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ فَسَكَتَ حَتَّى ظَنَنَّا أَنَّهُ سَيُسَمِّيهِ بِغَيْرِ اسْمِهِ قَالَ أَلَيْسَ ذَا الْحِجَّةِ قُلْنَا بَلَى قَالَ ‏ ‏أَيُّ بَلَدٍ هَذَا قُلْنَا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ فَسَكَتَ حَتَّى ظَنَنَّا أَنَّهُ سَيُسَمِّيهِ بِغَيْرِ اسْمِهِ قَالَ أَلَيْسَتْ الْبَلْدَةَ قُلْنَا بَلَى قَالَ فَإِنَّ دِمَاءَكُمْ وَأَمْوَالَكُمْ حَرَامٌ عَلَيْكُمْ كَحُرْمَةِ يَوْمِكُمْ هَذَا فِي شَهْرِكُمْ هَذَا فِي بَلَدِكُمْ هَذَا إِلَى يَوْمِ تَلْقَوْنَ رَبَّكُمْ تَبَارَكَ وَتَعَالَى أَلَا هَلْ بَلَّغْتُ قَالُوا نَعَمْ قَالَ اللَّهُمَّ اشْهَدْ لِيُبَلِّغْ الشَّاهِدُ الْغَائِبَ فَرُبَّ مُبَلَّغٍ ‏ ‏أَوْعَى ‏ ‏مِنْ سَامِعٍ أَلَا لَا تَرْجِعُنَّ بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ‏","","",""],[19595,19595,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏بَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ يَخْطُبُ إِذْ جَاءَ ‏ ‏الْحَسَنُ بْنُ عَلِيٍّ ‏ ‏فَصَعِدَ إِلَيْهِ الْمِنْبَرَ فَضَمَّهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَيْهِ وَمَسَحَ عَلَى رَأْسِهِ وَقَالَ ‏ ‏ابْنِي هَذَا سَيِّدٌ وَلَعَلَّ اللَّهَ أَنْ يُصْلِحَ عَلَى يَدَيْهِ بَيْنَ فِئَتَيْنِ عَظِيمَتَيْنِ مِنْ الْمُسْلِمِينَ ‏","","",""],[19596,19596,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَن ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَن ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏وَحُمَيْدٌ ‏ ‏وَيُونُسُ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَنَّ رَجُلًا قَالَ يَا رَسُولَ اللَّهِ ‏ ‏أَيُّ النَّاسِ خَيْرٌ قَالَ مَنْ طَالَ عُمْرُهُ وَحَسُنَ عَمَلُهُ قَالَ فَأَيُّ النَّاسِ شَرٌّ قَالَ مَنْ طَالَ عُمْرُهُ وَسَاءَ عَمَلُهُ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَن ‏ ‏ثَابِتٍ ‏ ‏وَيُونُسَ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏أَبِي بَكْرَةَ ‏ ‏فَذَكَرَهُ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَن ‏ ‏ثَابِتٍ ‏ ‏وَيُونُسَ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏أَبِي بَكْرَةَ ‏ ‏فَذَكَرَهُ ‏","","",""],[19597,19597,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَن ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَمْكُثُ أَبَوَا ‏ ‏الدَّجَّالِ ‏ ‏ثَلَاثِينَ عَامًا لَا يُولَدُ لَهُمَا وَلَدٌ ثُمَّ يُولَدُ لَهُمَا غُلَامٌ أَضَرُّ شَيْءٍ وَأَقَلُّهُ نَفْعًا تَنَامُ عَيْنَاهُ وَلَا يَنَامُ قَلْبُهُ ثُمَّ ‏ ‏نَعَتَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبَاهُ فَقَالَ أَبُوهُ رَجُلٌ طُوَالٌ ‏ ‏ضَرْبُ ‏ ‏اللَّحْمِ كَأَنَّ أَنْفَهُ مِنْقَارٌ وَأُمُّهُ امْرَأَةٌ ‏ ‏فِرْضَاخِيَّةٌ ‏ ‏طَوِيلَةُ الثَّدْيَيْنِ قَالَ ‏ ‏أَبُو بَكْرَةَ ‏ ‏فَسَمِعْنَا بِمَوْلُودٍ وُلِدَ فِي ‏ ‏الْيَهُودِ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَذَهَبْتُ أَنَا ‏ ‏وَالزُّبَيْرُ بْنُ الْعَوَّامِ ‏ ‏حَتَّى دَخَلْنَا عَلَى أَبَوَيْهِ فَإِذَا ‏ ‏نَعْتُ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِمَا فَقُلْنَا هَلْ لَكُمَا وَلَدٌ فَقَالَا مَكَثْنَا ثَلَاثِينَ عَامًا لَا يُولَدُ لَنَا وَلَدٌ ثُمَّ وُلِدَ لَنَا غُلَامٌ أَعْوَرُ ‏ ‏أَضَرُّ شَيْءٍ وَأَقَلُّهُ نَفْعًا تَنَامُ عَيْنَاهُ وَلَا يَنَامُ قَلْبُهُ فَخَرَجْنَا مِنْ عِنْدِهِمَا فَإِذَا الْغُلَامُ ‏ ‏مُنْجَدَلٌ ‏ ‏فِي ‏ ‏قَطِيفَةٍ ‏ ‏فِي الشَّمْسِ لَهُ ‏ ‏هَمْهَمَةٌ ‏ ‏قَالَ فَكَشَفْتُ عَنْ رَأْسِهِ فَقَالَ مَا قُلْتُمَا قُلْنَا وَهَلْ سَمِعْتَ قَالَ نَعَمْ إِنَّهُ تَنَامُ عَيْنَايَ وَلَا يَنَامُ قَلْبِي ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏وَهُوَ ‏ ‏ابْنُ صَيَّادٍ ‏","","",""],[19598,19598,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَن ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏وَفَدْنَا مَعَ ‏ ‏زِيَادٍ ‏ ‏إِلَى ‏ ‏مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏وَفِينَا ‏ ‏أَبُو بَكْرَةَ ‏ ‏فَلَمَّا قَدِمْنَا عَلَيْهِ لَمْ يُعْجَبْ بِوَفْدٍ مَا أُعْجِبَ بِنَا فَقَالَ يَا ‏ ‏أَبَا بَكْرَةَ ‏ ‏حَدِّثْنَا بِشَيْءٍ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْجِبُهُ الرُّؤْيَا الْحَسَنَةُ وَيَسْأَلُ عَنْهَا فَقَالَ ذَاتَ يَوْمٍ ‏ ‏أَيُّكُمْ رَأَى رُؤْيَا فَقَالَ رَجُلٌ أَنَا رَأَيْتُ كَأَنَّ مِيزَانًا دُلِّيَ مِنْ السَّمَاءِ فَوُزِنْتَ أَنْتَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏فَرَجَحْتَ ‏ ‏بِأَبِي بَكْرٍ ‏ ‏ثُمَّ وُزِنَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏فَرَجَحَ ‏ ‏أَبُو بَكْرٍ ‏ ‏بِعُمَرَ ‏ ‏ثُمَّ وُزِنَ ‏ ‏عُمَرُ ‏ ‏بِعُثْمَانَ ‏ ‏فَرَجَحَ ‏ ‏عُمَرُ ‏ ‏بِعُثْمَانَ ‏ ‏ثُمَّ رُفِعَ الْمِيزَانُ ‏ ‏فَاسْتَاءَ ‏ ‏لَهَا ‏ ‏وَقَدْ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏أَيْضًا فَسَاءَهُ ذَاكَ ‏ ‏ثُمَّ قَالَ خِلَافَةُ نُبُوَّةٍ ثُمَّ يُؤْتِي اللَّهُ تَبَارَكَ وَتَعَالَى الْمُلْكَ مَنْ يَشَاءُ قَالَ ‏ ‏فَزُخَّ ‏ ‏فِي أَقْفَائِنَا فَأُخْرِجْنَا فَقَالَ ‏ ‏زِيَادٌ ‏ ‏لَا أَبَا لَكَ أَمَا وَجَدْتَ حَدِيثًا غَيْرَ ذَا حَدِّثْهُ بِغَيْرِ ذَا قَالَ لَا وَاللَّهِ لَا أُحَدِّثُهُ إِلَّا بِذَا حَتَّى أُفَارِقَهُ فَتَرَكَنَا ثُمَّ دَعَا بِنَا فَقَالَ يَا ‏ ‏أَبَا بَكْرَةَ ‏ ‏حَدِّثْنَا بِشَيْءٍ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَبَكَعَهُ ‏ ‏بِهِ ‏ ‏فَزُخَّ ‏ ‏فِي أَقْفَائِنَا فَأُخْرِجْنَا فَقَالَ ‏ ‏زِيَادٌ ‏ ‏لَا أَبَا لَكَ أَمَا تَجِدُ حَدِيثًا غَيْرَ ذَا حَدِّثْهُ بِغَيْرِ ذَا فَقَالَ لَا وَاللَّهِ لَا أُحَدِّثُهُ إِلَّا بِهِ حَتَّى أُفَارِقَهُ قَالَ ثُمَّ تَرَكَنَا أَيَّامًا ثُمَّ دَعَا بِنَا فَقَالَ يَا ‏ ‏أَبَا بَكْرَةَ ‏ ‏حَدِّثْنَا بِشَيْءٍ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَبَكَعَهُ ‏ ‏فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏أَتَقُولُ الْمُلْكَ فَقَدْ رَضِينَا بِالْمُلْكِ ‏","","",""],[19599,19599,"","","‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَجَدْتُ هَذِهِ الْأَحَادِيثَ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ بْنُ خَلِيفَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَن ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَن ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَنَّ رَجُلًا قَالَ يَا رَسُولَ اللَّهِ ‏ ‏مَنْ خَيْرُ النَّاسِ قَالَ مَنْ طَالَ عُمْرُهُ وَحَسُنَ عَمَلُهُ قَالَ فَأَيُّ النَّاسِ شَرٌّ قَالَ مَنْ طَالَ عُمْرُهُ وَسَاءَ عَمَلُهُ ‏","","",""],[19600,19600,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏وَقَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَفَدْنَا إِلَى ‏ ‏مُعَاوِيَةَ ‏ ‏نُعَزِّيهِ مَعَ ‏ ‏زِيَادٍ ‏ ‏وَمَعَنَا ‏ ‏أَبُو بَكْرَةَ ‏ ‏فَلَمَّا قَدِمْنَا لَمْ يُعْجَبْ بِوَفْدٍ مَا أُعْجِبَ بِنَا فَقَالَ يَا ‏ ‏أَبَا بَكْرَةَ ‏ ‏حَدِّثْنَا بِشَيْءٍ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْجِبُهُ الرُّؤْيَا الْحَسَنَةُ وَيَسْأَلُ عَنْهَا وَإِنَّهُ قَالَ ذَاتَ يَوْمٍ ‏ ‏أَيُّكُمْ رَأَى رُؤْيَا فَقَالَ رَجُلٌ مِنْ الْقَوْمِ أَنَا رَأَيْتُ مِيزَانًا دُلِّيَ مِنْ السَّمَاءِ فَوُزِنْتَ فِيهِ أَنْتَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏فَرَجَحْتَ ‏ ‏بِأَبِي بَكْرٍ ‏ ‏ثُمَّ وُزِنَ فِيهِ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏فَرَجَحَ ‏ ‏أَبُو بَكْرٍ ‏ ‏بِعُمَرَ ‏ ‏ثُمَّ وُزِنَ فِيهِ ‏ ‏عُمَرُ ‏ ‏وَعُثْمَانُ ‏ ‏فَرَجَحَ ‏ ‏عُمَرُ ‏ ‏بِعُثْمَانَ ‏ ‏ثُمَّ رُفِعَ الْمِيزَانُ ‏ ‏فَاسْتَاءَ ‏ ‏لَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيْ أَوَّلَهَا فَقَالَ خِلَافَةُ نُبُوَّةٍ ثُمَّ يُؤْتِي اللَّهُ تَبَارَكَ وَتَعَالَى الْمُلْكَ مَنْ يَشَاءُ قَالَ ‏ ‏فَزُخَّ ‏ ‏فِي أَقْفَائِنَا وَأُخْرِجْنَا فَلَمَّا كَانَ مِنْ الْغَدِ عُدْنَا فَقَالَ يَا ‏ ‏أَبَا بَكْرَةَ ‏ ‏حَدِّثْنَا بِشَيْءٍ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَبَكَعَهُ ‏ ‏بِهِ ‏ ‏فَزُخَّ ‏ ‏فِي أَقْفَائِنَا فَلَمَّا كَانَ فِي الْيَوْمِ الثَّالِثِ عُدْنَا فَسَأَلَهُ أَيْضًا قَالَ ‏ ‏فَبَكَعَهُ ‏ ‏بِهِ فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏تَقُولُ إِنَّا مُلُوكٌ قَدْ رَضِينَا بِالْمُلْكِ ‏","","",""]];
